CREATE TABLE `equipments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL COMMENT '装备名称',
  `name_en` varchar(200) DEFAULT NULL COMMENT '英文名称',
  `equipment_type` enum('aircraft','naval_vessel','ground_vehicle','missile','firearm','artillery','radar_system','electronic_warfare','drone','nuclear','chemical','biological','cyber_weapon','other') DEFAULT NULL COMMENT '装备类型',
  `sub_type` varchar(100) DEFAULT NULL COMMENT '子类型',
  `manufacturer` varchar(200) DEFAULT NULL COMMENT '制造商',
  `origin_country_id` int DEFAULT NULL COMMENT '原产国ID',
  `operator_country_id` int DEFAULT NULL COMMENT '使用国ID',
  `operator_org_id` int DEFAULT NULL COMMENT '使用机构ID',
  `status` enum('active','retired','destroyed','captured','under_development') DEFAULT 'active' COMMENT '状态',
  `quantity` int DEFAULT '0' COMMENT '数量',
  `technical_specs` json DEFAULT NULL COMMENT '技术规格（JSON格式）',
  `capabilities` text COMMENT '作战能力描述',
  `deployment_location` varchar(255) DEFAULT NULL COMMENT '部署位置',
