--
-- Table structure for table `event_equipments`
--

DROP TABLE IF EXISTS `event_equipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_equipments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_id` int NOT NULL,
  `equipment_id` int NOT NULL,
  `usage_type` enum('used_by_attacker','used_by_defender','destroyed','captured','observed','other') DEFAULT NULL COMMENT '使用类型',
  `quantity` int DEFAULT '1' COMMENT '涉及数量',
  `notes` text COMMENT '备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=893 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件-装备关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

