DROP TABLE IF EXISTS `event_facilities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_facilities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_id` int NOT NULL,
  `facility_id` int NOT NULL,
  `impact_type` enum('attacked','defended','damaged','destroyed','captured','used_as_base','target','other') DEFAULT NULL COMMENT '受影响类型',
  `damage_assessment` text COMMENT '损害评估',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=371 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件-设施关联表';
