DROP TABLE IF EXISTS `event_organizations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_organizations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_id` int NOT NULL,
  `organization_id` int NOT NULL,
  `role` enum('attacker','defender','victim','mediator','supporter','observer','other') DEFAULT NULL COMMENT '参与角色',
  `involvement_description` text COMMENT '参与描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_event_org_role` (`event_id`,`organization_id`,`role`)
) ENGINE=InnoDB AUTO_INCREMENT=1211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件-机构关联表';
