DROP TABLE IF EXISTS `event_persons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_persons` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_id` int NOT NULL,
  `person_id` int NOT NULL,
  `role` enum('commander','perpetrator','victim','negotiator','witness','target','other') DEFAULT NULL COMMENT '角色',
  `involvement_description` text COMMENT '参与描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_event_person_role` (`event_id`,`person_id`,`role`)
) ENGINE=InnoDB AUTO_INCREMENT=1505 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件-人物关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

