DROP TABLE IF EXISTS `event_timeline`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_timeline` (
  `id` int NOT NULL AUTO_INCREMENT,
  `event_id` int NOT NULL,
  `timestamp` datetime NOT NULL COMMENT '进展时间',
  `title` varchar(500) NOT NULL COMMENT '进展标题',
  `description` text COMMENT '进展描述',
  `source` varchar(500) DEFAULT NULL COMMENT '信息来源',
  `source_url` text COMMENT '来源链接',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_event_time` (`event_id`,`timestamp`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件进展追踪表';
