--
-- Table structure for table `events`
--

DROP TABLE IF EXISTS `events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `events` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(500) NOT NULL COMMENT '事件标题',
  `event_code` varchar(50) DEFAULT NULL COMMENT '事件编号',
  `event_type` enum('military_conflict','terrorist_attack','political_crisis','diplomatic_tension','cyber_attack','intelligence_operation','military_exercise','weapon_test','border_incident','assassination','kidnapping','protest','coup_attempt','ceasefire_violation','sanctions','other') DEFAULT NULL COMMENT '事件类型',
  `sub_type` varchar(100) DEFAULT NULL COMMENT '事件子类型',
  `severity` enum('low','medium','high','critical','catastrophic') DEFAULT 'medium' COMMENT '严重程度',
  `status` enum('ongoing','concluded','investigating','unconfirmed') DEFAULT 'ongoing' COMMENT '事件状态',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `reported_time` datetime DEFAULT NULL COMMENT '首次报道时间',
  `primary_location` varchar(500) DEFAULT NULL COMMENT '主要地点',
  `location_detail` varchar(500) DEFAULT NULL COMMENT '地点详情',
  `country_id` int DEFAULT NULL COMMENT '发生国家ID',
  `region_id` int DEFAULT NULL COMMENT '发生地区ID',
  `coordinates` point DEFAULT NULL COMMENT '地理坐标',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '纬度',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '经度',
  `casualties_killed` int DEFAULT '0' COMMENT '死亡人数',
  `casualties_injured` int DEFAULT '0' COMMENT '受伤人数',
  `casualties_missing` int DEFAULT '0' COMMENT '失踪人数',
  `casualties_data_source` varchar(255) DEFAULT NULL COMMENT '伤亡数据来源',
  `reliability` enum('confirmed','likely','possible','unlikely','false') DEFAULT 'likely' COMMENT '信息可靠性',
  `information_source` varchar(500) DEFAULT NULL COMMENT '信息来源',
  `source_url` text COMMENT '来源链接',
  `summary` text COMMENT '事件摘要',
  `detailed_description` text COMMENT '详细描述',
  `analysis` text COMMENT '分析评估',
  `immediate_impact` text COMMENT '直接影响',
  `potential_consequences` text COMMENT '潜在后果',
  `tags` json DEFAULT NULL COMMENT '标签（JSON数组）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `event_code` (`event_code`)
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件表';
/*!40101 SET character_set_client = @saved_cs_client */;

