INSERT INTO `events` VALUES (1,'俄军对基辅发动大规模导弹袭击','EVT-2024-001','military_conflict',NULL,'critical','ongoing','2024-01-15 03:42:00',NULL,NULL,'乌克兰基辅','基辅市中心及周边区域',4,NULL,NULL,50.45010000,30.52340000,45,120,15,NULL,'confirmed','乌克兰国防部官方通报、社交媒体多方视频验证',NULL,'俄军向基辅发射了超过40枚巡航导弹和弹道导弹，乌防空系统拦截了约70%','凌晨3时42分，俄军从黑海舰队舰艇、图-95MS战略轰炸机和地面发射装置向基辅发起三波次导弹攻击。据乌军方统计，共发射41枚各型导弹，包括Kh-101巡航导弹、匕首高超音速导弹和口径巡航导弹。乌防空部队宣称击落29枚来袭导弹。袭击导致一栋公寓楼严重受损，数座变电站被毁，部分地区断电。','1. 这是俄军2024年第一次对基辅的大规模空袭，显示其导弹库存仍然充裕\n2. 攻击时间选择凌晨，旨在平民目标，有报复性质\n3. 匕首高超音速导弹的实战使用频率增加，值得关注\n4. 乌军拦截率70%较去年提升，西方防空系统部署见效',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(2,'胡塞武装在红海袭击商船','EVT-2024-002','terrorist_attack',NULL,'high','ongoing','2024-01-18 14:20:00',NULL,NULL,'红海曼德海峡附近','也门沿岸120海里海域',NULL,NULL,NULL,14.00000000,42.00000000,0,3,2,NULL,'confirmed','英国海事贸易运营局(UKMTO)、美军中央司令部通报',NULL,'悬挂利比里亚国旗的散货船遭胡塞武装反舰导弹和无人机攻击，船只起火，3名船员受伤','14时20分，一艘从中国开往意大利的散货船在经过曼德海峡时，遭到胡塞武装的多轮攻击。胡塞方面先发射了两枚反舰弹道导弹，均被美国海军驱逐舰拦截。随后派出3架见证者-136自杀式无人机，其中一架命中船尾导致火灾。美国海军派出直升机营救了受伤船员，并将船只护送至安全水域。','1. 胡塞武装持续红海攻击，意图施压以色列在加沙停火\n2. 反舰弹道导弹实战化值得警惕\n3. 国际航运成本飙升，全球供应链承压\n4. 美军护航行动面临消耗战考验',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(3,'解放军在台海举行大规模联合军演','EVT-2024-003','military_exercise',NULL,'high','concluded','2024-01-20 06:00:00','2024-01-22 18:00:00',NULL,'台湾海峡及周边海空域','台岛北部、西南、东南海空域',3,NULL,NULL,24.50000000,121.00000000,0,0,0,NULL,'confirmed','中国国防部新闻发言人、台防务部门通告',NULL,'解放军东部战区组织海空兵力进行联合演练，包含环台岛战备警巡，模拟对陆打击和反介入作战','1月20日至22日，东部战区组织海军驱逐舰、护卫舰，空军歼-16、歼-20、轰-6K等兵力，在台湾海峡及东南海域实施多科目演练。演练重点包括：联合封锁、对海突击、对陆精确打击、区域防空等。台军紧急出动F-16V和幻影2000战机应对，双方最近距离据称仅5海里。','1. 演习范围首次覆盖台岛西南170海里范围\n2. 歼-20疑似参与演习，首次在台海附近活动\n3. 时间选择台湾地区选举后一周，政治信号明确\n4. 模拟对陆精确打击预示高精度武器部署准备',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(4,'以色列空袭伊朗核设施未遂','EVT-2024-004','military_conflict',NULL,'critical','investigating','2024-02-03 23:45:00',NULL,NULL,'伊朗伊斯法罕省','纳坦兹铀浓缩设施50公里区域',5,NULL,NULL,33.51000000,51.91900000,3,8,0,NULL,'likely','多方情报来源、卫星图像、伊朗官方声明矛盾',NULL,'伊朗防空系统在纳坦兹附近拦截多个不明飞行物，怀疑为以色列无人机或导弹','当地时间23时45分，伊斯法罕省多地传出爆炸声。伊朗防空部队宣称成功拦截数架小型无人机。但商业卫星随后几天拍摄的图像显示，纳坦兹设施附近一个新防空阵地遭到精确打击。以色列政府拒绝评论。伊朗最初否认损失，后承认\"有限损害\"。美国情报报告显示以色列可能使用了新型隐身巡航导弹。','1. 攻击路径研判：可能经由伊拉克或叙利亚领空进入\n2. 打击目标选择精准，显示高价值情报\n3. 伊朗核设施外围出现不明辐射值异常\n4. 若证实为以色列所为，将是2024年最重大的秘密行动',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(5,'朝鲜试射新型固体燃料洲际导弹','EVT-2024-005','weapon_test',NULL,'critical','concluded','2024-02-10 07:30:00','2024-02-10 08:15:00',NULL,'朝鲜平壤顺安机场','向东部海域试射',7,NULL,NULL,39.20000000,125.80000000,0,0,0,NULL,'confirmed','朝鲜朝中社报道、韩国联合参谋本部、日本防卫省',NULL,'朝鲜试射了一枚新型固体燃料洲际弹道导弹，飞行高度6500公里，飞行距离约1100公里，落入了日本专属经济区外的日本海','清晨7时30分，朝鲜从平壤顺安机场附近的移动发射车发射了一枚导弹。导弹以高弹道方式飞行，最高点6500公里。这是朝鲜首次测试固体燃料洲际导弹，被认为技术取得重大突破。导弹最终落入北海道以西约250公里的日本海。美日韩紧急召开电话会议，联合国安理会宣布将召开紧急会议。','1. 固体燃料导弹生存能力远超液体燃料型号\n2. 高弹道试射方式规避他国领土\n3. 射程推算可达12000公里，覆盖美国本土大部分地区\n4. 朝鲜核力量从核威慑向实战化转变趋势明显',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(6,'美国关键基础设施遭网络攻击','EVT-2024-006','cyber_attack',NULL,'high','investigating','2024-02-15 09:00:00',NULL,NULL,'美国多州','得克萨斯州、加利福尼亚州等地',1,NULL,NULL,30.26720000,-97.74310000,0,0,0,NULL,'confirmed','美国网络安全和基础设施安全局(CISA)通报',NULL,'德克萨斯州电网和水处理设施遭受勒索软件和工业控制系统攻击，部分服务中断','2月15日，得克萨斯州电力可靠性委员会(ERCOT)及多个水处理厂同时报告网络异常。攻击者利用VPN漏洞入侵工业控制系统，尝试篡改水处理化学制剂投放参数。电网方面，勒索软件导致部分配电系统离线，影响约15万户居民用电。FBI紧急介入调查，初期指向某俄罗斯黑客组织，但证据仍不充分。','1. 攻击特征与俄支持的黑客组织\"暗能量\"手法相似\n2. 精确控制工控系统需要极深的专业知识\n3. 电网和水务同时遇袭显示高度协同\n4. 非战时关键基础设施攻击可能触发北约第五条讨论',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(7,'美军空袭叙利亚境内伊朗目标','EVT-2024-007','military_conflict',NULL,'high','concluded','2024-02-20 01:30:00','2024-02-20 03:00:00',NULL,'叙利亚代尔祖尔省','迈亚丁地区的军事基地',8,NULL,NULL,34.88000000,40.57000000,18,25,0,NULL,'confirmed','美国中央司令部声明、叙利亚人权观察组织',NULL,'美军派遣F-15E和MQ-9对叙利亚境内伊斯兰革命卫队及其支持的民兵组织目标实施精确打击','凌晨1时30分，美军从约旦空军基地起飞6架F-15E战斗轰炸机，并配合多架MQ-9死神无人机，攻击了伊朗革命卫队位于代尔祖尔省迈亚丁地区的3个军事设施。目标包括军火库、指挥所以及无人机发射基地。攻击造成18名武装人员死亡，包括2名伊朗军事顾问。','1. 这是2024年美军首次公开打击伊朗军事人员\n2. 信息来源显示攻击是对近期针对美军基地袭击的回应\n3. B-1B轰炸机未出动显示战争升级控制\n4. 伊朗未立即报复,显示其反应谨慎,避免与美直接冲突',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(8,'俄罗斯宣布退出《全面禁止核试验条约》','EVT-2024-008','political_crisis',NULL,'catastrophic','ongoing','2024-03-01 10:00:00',NULL,NULL,'俄罗斯莫斯科','俄罗斯联邦议会',2,NULL,NULL,55.75580000,37.61730000,0,0,0,NULL,'confirmed','俄罗斯总统新闻秘书佩斯科夫宣布',NULL,'俄罗斯国家杜马通过决议，正式撤销对《全面禁止核试验条约》的批准，普京总统签署相关法律','3月1日，俄罗斯联邦议会上下两院以全票通过撤销《全面禁止核试验条约》批准的法案。普京总统随后签署使其成为法律。俄方称此举是为\"与美国在核试验领域对等\"。美国从未批准该条约。此决定允许俄罗斯恢复核试验，引发国际社会强烈反应。美国能源部随后宣布保持内华达试验场的高度准备状态。','1. 核军备竞赛风险急剧升高\n2. 新地岛核试验场据卫星图像显示已经准备\n3. 可能试射新型RS-28萨尔马特的测试活动增加\n4. 此举被视为俄罗斯对西方压力的极限施压策略',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(9,'中印边境再次发生冲突','EVT-2024-009','border_incident',NULL,'high','investigating','2024-03-05 14:00:00',NULL,NULL,'阿鲁纳恰尔邦（中国藏南地区）','达旺地区实际控制线附近',3,NULL,NULL,27.57000000,91.88000000,5,18,3,NULL,'confirmed','印度陆军发言人、中国外交部回应',NULL,'中印边防部队在达旺地区发生群体性冲突，双方使用冷兵器，据报有人员伤亡','3月5日下午，印度方面称中国人民解放军士兵越过实际控制线，双方发生对峙并迅速升级为冲突。据印方消息，约50名解放军战士和70名印度军警卷入冲突，使用棍棒和石块。印方称己方5人死亡，18人受伤；中国外交部表示边界问题沟通渠道畅通，呼吁和平解决。','1. 达旺是1962年中印战争的主要战场之一\n2. 此次冲突规模超2020年加勒万河谷事件\n3. 双方均未使用枪支,显示管控意愿但摩擦烈度在上升\n4. 印度国内选举临近可能影响事态',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(10,'卫星图像显示朝鲜丰溪里核试验场异常活动','EVT-2024-010','military_conflict',NULL,'critical','unconfirmed','2024-03-10 08:00:00',NULL,NULL,'朝鲜咸镜北道','丰溪里核试验场3号坑道',7,NULL,NULL,41.27800000,129.08700000,0,0,0,NULL,'possible','Maxar商业卫星图像、国际原子能机构IAEA',NULL,'商业卫星拍到丰溪里核试验场出现大量人员和设备，疑似准备进行第七次核试验','3月10日，Maxar Technologies发布的商业卫星图像显示，朝鲜丰溪里核试验场的3号坑道附近出现密集活动。包括超过50名技术人员、多辆卡车以及电缆铺设作业。与历次核试验前兆高度吻合。韩国情报部门评估认为朝鲜可能在未来两周内核试验。国际原子能机构总干事对此表示严重关切。','1. 3号坑道在2018年炸毁后，2022年开始重建\n2. 如果进行核试验,将是2017年来的首次\n3. 小型化战术核武器测试可能性大\n4. 朝鲜可能在韩国选举期间进行以最大化政治影响',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(11,'北约舰艇在黑海与俄海军对峙','EVT-2024-011','military_conflict',NULL,'high','ongoing','2024-03-12 06:00:00',NULL,NULL,'黑海国际水域','克里米亚以南约200海里',4,NULL,NULL,44.51000000,34.17000000,0,0,0,NULL,'confirmed','北约海上司令部、俄罗斯黑海舰队',NULL,'北约常设海上编队与俄黑海舰队在黑海国际水域发生近距离对峙，双方舰艇相距不足50米','北约常设第2海上集团派出3艘护卫舰进入黑海进行\"航行自由\"行动。俄黑海舰队派出基洛夫级巡洋舰和2艘护卫舰跟踪监视。俄战机进行了低空飞越，北约舰艇启动电子对抗系统。整个对峙过程持续约6小时，最终双方各自离开。这是2022年俄乌冲突以来北约和俄军最接近直接摩擦的一次。','1. 北约动用基洛夫级来应对显示重视程度\n2. 电子对抗手段的运用说明现代海战模式\n3. 双方均未开火但距离火线仅一步之遥\n4. 黑海已成为2024年欧洲最危险的海域',NULL,NULL,NULL,'2026-04-26 13:17:08','2026-04-26 13:17:08'),(12,'越南在地中海试射新型导弹','EVT-2024-0012','border_incident','skirmish','high','concluded','2025-03-13 05:45:00',NULL,NULL,'地中海',NULL,35,NULL,NULL,-49.78907103,152.20223689,428,0,0,NULL,'likely',NULL,NULL,'越南在地中海试射新型导弹发生于地中海','2025-03-13 05:45:00，越南在地中海试射新型导弹。据当地媒体报道，冲突造成428人死亡、0人受伤。',NULL,NULL,NULL,NULL,'2026-05-10 01:05:47','2026-05-10 01:05:47'),(13,'德国在黑海建立新的军事基地','EVT-2024-0013','military_exercise','missile_test','medium','unconfirmed','2023-08-08 10:35:00',NULL,NULL,'黑海',NULL,25,NULL,NULL,-51.41220850,-105.03426751,0,820,0,NULL,'possible',NULL,NULL,'德国在黑海建立新的军事基地发生于黑海','2023-08-08 10:35:00，德国在黑海建立新的军事基地。据当地媒体报道，冲突造成0人死亡、820人受伤。',NULL,NULL,NULL,NULL,'2026-05-10 01:05:47','2026-05-10 01:05:47'),(14,'墨西哥与伊朗在地中海发生海上对峙','EVT-2023-0014','diplomatic_tension','skirmish','critical','unconfirmed','2023-10-12 18:57:00',NULL,NULL,'地中海',NULL,13,NULL,NULL,-33.26398135,135.87312694,0,0,0,NULL,'likely',NULL,NULL,'墨西哥与伊朗在地中海发生海上对峙发生于地中海','2023-10-12 18:57:00，墨西哥与伊朗在地中海发生海上对峙。据当地媒体报道，冲突造成0人死亡、0人受伤。',NULL,NULL,NULL,NULL,'2026-05-10 01:05:47','2026-05-10 01:05:47'),(15,'马来西亚情报机构被曝在德黑兰从事间谍活动','EVT-2024-0015','border_incident','counter_terrorism','medium','investigating','2025-02-22 12:24:00',NULL,NULL,'德黑兰',NULL,9,NULL,NULL,-42.54393174,-154.17144125,88,385,0,NULL,'confirmed',NULL,NULL,'马来西亚情报机构被曝在德黑兰从事间谍活动发生于德黑兰','2025-02-22 12:24:00，马来西亚情报机构被曝在德黑兰从事间谍活动。据当地媒体报道，冲突造成88人死亡、385人受伤。',NULL,NULL,NULL,NULL,'2026-05-10 01:05:47','2026-05-10 01:05:47'),(16,'伊斯坦布尔核电站遭到墨西哥网络攻击','EVT-2025-0016','terrorist_attack','economic_sanctions','low','concluded','2024-07-05 13:59:00',NULL,NULL,'伊斯坦布尔',NULL,34,NULL,NULL,67.86528276,174.12061595,500,989,0,NULL,'likely',NULL,NULL,'伊斯坦布尔核电站遭到墨西哥网络攻击发生于伊斯坦布尔','2024-07-05 13:59:00，伊斯坦布尔核电站遭到墨西哥网络攻击。据当地媒体报道