--
-- Table structure for table `facilities`
--

DROP TABLE IF EXISTS `facilities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `facilities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL COMMENT '设施名称',
  `name_en` varchar(200) DEFAULT NULL COMMENT '英文名称',
  `facility_type` enum('military_base','naval_base','air_base','missile_site','radar_station','command_center','intelligence_facility','nuclear_facility','chemical_plant','oil_refinery','port','airport','government_building','power_plant','communication_hub','other') DEFAULT NULL COMMENT '设施类型',
  `country_id` int DEFAULT NULL COMMENT '所属国家ID',
  `operator_org_id` int DEFAULT NULL COMMENT '运营机构ID',
  `coordinates` point DEFAULT NULL COMMENT '地理坐标',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '纬度',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '经度',
  `address` varchar(500) DEFAULT NULL COMMENT '地址',
  `strategic_importance` enum('low','medium','high','critical') DEFAULT 'medium' COMMENT '战略重要性',
  `security_level` enum('public','restricted','secret','top_secret') DEFAULT 'restricted' COMMENT '安全级别',
  `status` enum('operational','non_operational','destroyed','captured','under_construction') DEFAULT 'operational' COMMENT '状态',
  `capacity` text COMMENT '容量/能力描述',
  `defense_systems` text COMMENT '防御系统',
  `established_date` date DEFAULT NULL COMMENT '建立日期',
  `description` text COMMENT '描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='重要设施表';
/*!40101 SET character_set_client = @saved_cs_client */;

