--
-- Table structure for table `organizations`
--

DROP TABLE IF EXISTS `organizations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `organizations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL COMMENT '机构名称',
  `name_en` varchar(200) DEFAULT NULL COMMENT '英文名称',
  `abbreviation` varchar(50) DEFAULT NULL COMMENT '缩写',
  `org_type` enum('government','military','intelligence','terrorist','rebel','corporate','ngo','media','other') DEFAULT NULL COMMENT '机构类型',
  `country_id` int DEFAULT NULL COMMENT '所属国家/地区ID',
  `parent_org_id` int DEFAULT NULL COMMENT '上级机构ID',
  `ideology` varchar(200) DEFAULT NULL COMMENT '意识形态/政治立场',
  `threat_level` enum('low','medium','high','critical') DEFAULT 'low' COMMENT '威胁等级',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否活跃',
  `established_date` date DEFAULT NULL COMMENT '成立日期',
  `dissolved_date` date DEFAULT NULL COMMENT '解散日期',
  `headquarters_location` varchar(255) DEFAULT NULL COMMENT '总部位置',
  `description` text COMMENT '描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='机构表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `organizations`
--

LOCK TABLES `organizations` WRITE;
/*!40000 ALTER TABLE `organizations` DISABLE KEYS */;
