--
-- Table structure for table `persons`
--

DROP TABLE IF EXISTS `persons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `persons` (
  `id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(200) NOT NULL COMMENT '姓名',
  `name_en` varchar(200) DEFAULT NULL COMMENT '英文姓名',
  `alias` varchar(500) DEFAULT NULL COMMENT '别名（多个用逗号分隔）',
  `gender` enum('male','female','other') DEFAULT NULL COMMENT '性别',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `death_date` date DEFAULT NULL COMMENT '死亡日期',
  `nationality_id` int DEFAULT NULL COMMENT '国籍ID',
  `role` enum('political_leader','military_commander','intelligence_officer','terrorist','diplomat','journalist','business_leader','other') DEFAULT NULL COMMENT '角色类型',
  `rank_title` varchar(100) DEFAULT NULL COMMENT '军衔/职级',
  `current_status` enum('active','detained','deceased','missing','retired') DEFAULT 'active' COMMENT '当前状态',
  `threat_level` enum('low','medium','high','critical') DEFAULT 'low' COMMENT '威胁等级',
  `is_key_figure` tinyint(1) DEFAULT '0' COMMENT '是否关键人物',
  `biography` text COMMENT '个人简介',
  `photo_url` varchar(500) DEFAULT NULL COMMENT '照片URL',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='人物表';
/*!40101 SET character_set_client = @saved_cs_client */;

