INSERT INTO `text_sources` VALUES (2,'伊朗宣布处决两名向以色列提供情报的间谍','新华社德黑兰5月2日电　据伊朗法尔斯通讯社2日报道，伊朗处决了两名为以色列情报和特勤局（摩萨德）工作的间谍。\n\n  报道说，在经过伊朗司法系统审理并经伊朗最高法院核准判决后，雅库布·卡林普尔和纳赛尔·贝克尔扎德因向以色列政府以及情报机构提供情报和从事间谍活动，被处以绞刑。\n\n  报道称，卡林普尔与摩萨德合作，向相关情报人员传递涉及国家安全的敏感信息，而贝克尔扎德曾在多个敏感区域进行异常活动，并在摩萨德的指使下，收集有关政府、宗教及地方人士的信息，以及包括纳坦兹地区在内的重要设施情况。','paste',NULL,244,'2026-05-05 03:49:51'),(3,'俄军对基辅发动大规模导弹袭击','俄军对基辅发动大规模导弹袭击\n\n俄军向基辅发射了超过40枚巡航导弹和弹道导弹，乌防空系统拦截了约70%\n\n凌晨3时42分，俄军从黑海舰队舰艇、图-95MS战略轰炸机和地面发射装置向基辅发起三波次导弹攻击。据乌军方统计，共发射41枚各型导弹，包括Kh-101巡航导弹、匕首高超音速导弹和口径巡航导弹。乌防空部队宣称击落29枚来袭导弹。袭击导致一栋公寓楼严重受损，数座变电站被毁，部分地区断电。','paste',NULL,195,'2026-06-01 13:20:57'),(4,'胡塞武装在红海袭击商船','胡塞武装在红海袭击商船\n\n悬挂利比里亚国旗的散货船遭胡塞武装反舰导弹和无人机攻击，船只起火，3名船员受伤\n\n14时20分，一艘从中国开往意大利的散货船在经过曼德海峡时，遭到胡塞武装的多轮攻击。胡塞方面先发射了两枚反舰弹道导弹，均被美国海军驱逐舰拦截。随后派出3架见证者-136自杀式无人机，其中一架命中船尾导致火灾。美国海军派出直升机营救了受伤船员，并将船只护送至安全水域。','paste',NULL,187,'2026-06-01 13:22:00'),(5,'解放军在台海举行大规模联合军演','解放军在台海举行大规模联合军演\n\n解放军东部战区组织海空兵力进行联合演练，包含环台岛战备警巡，模拟对陆打击和反介入作战\n\n1月20日至22日，东部战区组织海军驱逐舰、护卫舰，空军歼-16、歼-20、轰-6K等兵力，在台湾海峡及东南海域实施多科目演练。演练重点包括：联合封锁、对海突击、对陆精确打击、区域防空等。台军紧急出动F-16V和幻影2000战机应对，双方最近距离据称仅5海里。','paste',NULL,191,'2026-06-01 13:23:02'),(6,'以色列空袭伊朗核设施未遂','以色列空袭伊朗核设施未遂\n\n伊朗防空系统在纳坦兹附近拦截多个不明飞行物，怀疑为以色列无人机或导弹\n\n当地时间23时45分，伊斯法罕省多地传出爆炸声。伊朗防空部队宣称成功拦截数架小型无人机。但商业卫星随后几天拍摄的图像显示，纳坦兹设施附近一个新防空阵地遭到精确打击。以色列政府拒绝评论。伊朗最初否认损失，后承认\"有限损害\"。美国情报报告显示以色列可能使用了新型隐身巡航导弹。','paste',NULL,186,'2026-06-01 13:24:04'),(7,'朝鲜试射新型固体燃料洲际导弹','朝鲜试射新型固体燃料洲际导弹\n\n朝鲜试射了一枚新型固体燃料洲际弹道导弹，飞行高度6500公里，飞行距离约1100公里，落入了日本专属经济区外的日本海\n\n清晨7时30分，朝鲜从平壤顺安机场附近的移动发射车发射了一枚导弹。导弹以高弹道方式飞行，最高点6500公里。这是朝鲜首次测试固体燃料洲际导弹，被认为技术取得重大突破。导弹最终落入北海道以西约250公里的日本海。美日韩紧急召开电话会议，联合国安理会宣布将召开紧急会议。','paste',NULL,209,'2026-06-01 13:25:06'),(8,'美国关键基础设施遭网络攻击','美国关键基础设施遭网络攻击\n\n德克萨斯州电网和水处理设施遭受勒索软件和工业控制系统攻击，部分服务中断\n\n2月15日，得克萨斯州电力可靠性委员会(ERCOT)及多个水处理厂同时报告网络异常。攻击者利用VPN漏洞入侵工业控制系统，尝试篡改水处理化学制剂投放参数。电网方面，勒索软件导致部分配电系统离线，影响约15万户居民用电。FBI紧急介入调查，初期指向某俄罗斯黑客组织，但证据仍不充分。','paste',NULL,192,'2026-06-01 13:26:09'),(9,'美军空袭叙利亚境内伊朗目标','美军空袭叙利亚境内伊朗目标\n\n美军派遣F-15E和MQ-9对叙利亚境内伊斯兰革命卫队及其支持的民兵组织目标实施精确打击\n\n凌晨1时30分，美军从约旦空军基地起飞6架F-15E战斗轰炸机，并配合多架MQ-9死神无人机，攻击了伊朗革命卫队位于代尔祖尔省迈亚丁地区的3个军事设施。目标包括军火库、指挥所以及无人机发射基地。攻击造成18名武装人员死亡，包括2名伊朗军事顾问。','paste',NULL,183,'2026-06-01 13:27:11'),(10,'俄罗斯宣布退出《全面禁止核试验条约》','俄罗斯宣布退出《全面禁止核试验条约》\n\n俄罗斯国家杜马通过决议，正式撤销对《全面禁止核试验条约》的批准，普京总统签署相关法律\n\n3月1日，俄罗斯联邦议会上下两院以全票通过撤销《全面禁止核试验条约》批准的法案。普京总统随后签署使其成为法律。俄方称此举是为\"与美国在核试验领域对等\"。美国从未批准该条约。此决定允许俄罗斯恢复核试验，引发国际社会强烈反应。美国能源部随后宣布保持内华达试验场的高度准备状态。','paste',NULL,200,'2026-06-01 13:28:13'),(11,'中印边境再次发生冲突','中印边境再次发生冲突\n\n中印边防部队在达旺地区发生群体性冲突，双方使用冷兵器，据报有人员伤亡\n\n3月5日下午，印度方面称中国人民解放军士兵越过实际控制线，双方发生对峙并迅速升级为冲突。据印方消息，约50名解放军战士和70名印度军警卷入冲突，使用棍棒和石块。印方称己方5人死亡，18人受伤；中国外交部表示边界问题沟通渠道畅通，呼吁和平解决。','paste',NULL,169,'2026-06-01 13:29:15'),(12,'卫星图像显示朝鲜丰溪里核试验场异常活动','卫星图像显示朝鲜丰溪里核试验场异常活动\n\n商业卫星拍到丰溪里核试验场出现大量人员和设备，疑似准备进行第七次核试验\n\n3月10日，Maxar Technologies发布的商业卫星图像显示，朝鲜丰溪里核试验场的3号坑道附近出现密集活动。包括超过50名技术人员、多辆卡车以及电缆铺设作业。与历次核试验前兆高度吻合。韩国情报部门评估认为朝鲜可能在未来两周内核试验。国际原子能机构总干事对此表示严重关切。','paste',NULL,198,'2026-06-01 13:30:18'),(13,'北约舰艇在黑海与俄海军对峙','北约舰艇在黑海与俄海军对峙\n\n北约常设海上编队与俄黑海舰队在黑海国际水域发生近距离对峙，双方舰艇相距不足50米\n\n北约常设第2海上集团派出3艘护卫舰进入黑海进行\"航行自由\"行动。俄黑海舰队派出基洛夫级巡洋舰和2艘护卫舰跟踪监视。俄战机进行了低空飞越，北约舰艇启动电子对抗系统。整个对峙过程持续约6小时，最终双方各自离开。这是2022年俄乌冲突以来北约和俄军最接近直接摩擦的一次。','paste',NULL,189,'2026-06-01 13:31:20'),(14,'越南在地中海试射新型导弹','越南在地中海试射新型导弹\n\n越南在地中海试射新型导弹发生于地中海\n\n2025-03-13 05:45:00，越南在地中海试射新型导弹。据当地媒体报道，冲突造成428人死亡、0人受伤。','paste',NULL,91,'2026-06-01 13:32:22'),(15,'德国在黑海建立新的军事基地','德国在黑海建立新的军事基地\n\n德国在黑海建立新的军事基地发生于黑海\n\n2023-08-08 10:35:00，德国在黑海建立新的军事基地。据当地媒体报道，冲突造成0人死亡、820人受伤。','paste',NULL,93,'2026-06-01 13:33:24'),(16,'墨西哥与伊朗在地中海发生海上对峙','墨西哥与伊朗在地中海发生海上对峙\n\n墨西哥与伊朗在地中海发生海上对峙发生于地中海\n\n2023-10-12 18:57:00，墨西哥与伊朗在地中海发生海上对峙。据当地媒体报道，冲突造成0人死亡、0人受伤。','paste',NULL,101,'2026-06-01 13:34:27'),(17,'马来西亚情报机构被曝在德黑兰从事间谍活动','马来西亚情报机构被曝在德黑兰从事间谍活动\n\n马来西亚情报机构被曝在德黑兰从事间谍活动发生于德黑兰\n\n2025-02-22 12:24:00，马来西亚情报机构被曝在德黑兰从事间谍活动。据当地媒体报道，冲突造成88人死亡、385人受伤。','paste',NULL,116,'2026-06-01 13:35:29'),(18,'伊斯坦布尔核电站遭到墨西哥网络攻击','伊斯坦布尔核电站遭到墨西哥网络攻击\n\n伊斯坦布尔核电站遭到墨西哥网络攻击发生于伊斯坦布尔\n\n2024-07-05 13:59:00，伊斯坦布尔核电站遭到墨西哥网络攻击。据当地媒体报道，冲突造成500人死亡、989人受伤。','paste',NULL,110,'2026-06-01 13:36:31'),(19,'新加坡与乌克兰在堪培拉发生海上对峙','新加坡与乌克兰在堪培拉发生海上对峙\n\n新加坡与乌克兰在堪培拉发生海上对峙发生于堪培拉\n\n2024-08-15 05:02:00，新加坡与乌克兰在堪培拉发生海上对峙。据当地媒体报道，冲突造成155人死亡、0人受伤。','paste',NULL,106,'2026-06-01 13:37:33'),(20,'波兰无人机在北极圈执行侦察任务时被击落','波兰无人机在北极圈执行侦察任务时被击落\n\n波兰无人机在北极圈执行侦察任务时被击落发生于北极圈\n\n2024-04-28 15:11:00，波兰无人机在北极圈执行侦察任务时被击落。据当地媒体报道，冲突造成0人死亡、172人受伤。','paste',NULL,112,'2026-06-01 13:38:36'),(21,'耶路撒冷发生军事政变，埃及介入','耶路撒冷发生军事政变，埃及介入\n\n耶路撒冷发生军事政变，埃及介入发生于耶路撒冷\n\n2023-07-19 17:40:00，耶路撒冷发生军事政变，埃及介入。据当地媒体报道，冲突造成0人死亡、0人受伤。','paste',NULL,99,'2026-06-01 13:39:38'),(22,'乌克兰无人机在基辅执行侦察任务时被击落','乌克兰无人机在基辅执行侦察任务时被击落\n\n乌克兰无人机在基辅执行侦察任务时被击落发生于基辅\n\n2024-05-30 06:02:00，乌克兰无人机在基辅执行侦察任务时被击落。据当地媒体报道，冲突造成304人死亡、0人受伤。','paste',NULL,111,'2026-06-01 13:40:38'),(43,'英国宣布退出伦敦国际条约','英国宣布退出伦敦国际条约\n\n英国宣布退出伦敦国际条约发生于伦敦\n\n2024-03-23 19:41:00，英国宣布退出伦敦国际条约。据当地媒体报道，冲突造成0人死亡、149人受伤。','paste',NULL,90,'2026-06-01 13:41:27'),(44,'法国宣布退出东南亚国际条约','法国宣布退出东南亚国际条约\n\n法国宣布退出东南亚国际条约发生于东南亚\n\n2024-09-12 12:03:00，法国宣布退出东南亚国际条约。据当地媒体报道，冲突造成0人死亡、1094人受伤。','paste',NULL,95,'2026-06-01 13:41:27'),(45,'墨西哥航母战斗群进入堪培拉','墨西哥航母战斗群进入堪培拉\n\n墨西哥航母战斗群进入堪培拉发生于堪培拉\n\n2023-02-03 01:21:00，墨西哥航母战斗群进入堪培拉。据当地媒体报道，冲突造成0人死亡、433人受伤。','paste',NULL,94,'2026-06-01 13:41:27'),(46,'菲律宾在东京试射新型导弹','菲律宾在东京试射新型导弹\n\n菲律宾在东京试射新型导弹发生于东京\n\n2023-08-06 03:31:00，菲律宾在东京试射新型导弹。据当地媒体报道，冲突造成32人死亡、0人受伤。','paste',NULL,89,'2026-06-01 13:41:27'),(47,'南非向太平洋派遣维和部队','南非向太平洋派遣维和部队\n\n南非向太平洋派遣维和部队发生于太平洋\n\n2023-12-24 19:44:00，南非向太平洋派遣维和部队。据当地媒体报道，冲突造成0人死亡、0人受伤。','paste',NULL,89,'2026-06-01 13:41:27'),(48,'波兰与意大利在苏伊士运河发生边境冲突','波兰与意大利在苏伊士运河发生边境冲突\n\n波兰与意大利在苏伊士运河发生边境冲突发生于苏伊士运河\n\n2024-05-29 10:39:00，波兰与意大利在苏伊士运河发生边境冲突。据当地媒体报道，冲突造成0人死亡、1516人受伤。','paste',NULL,112,'2026-06-01 13:41:27'),(49,'乌克兰宣布对加拿大实施经济制裁','乌克兰宣布对加拿大实施经济制裁\n\n乌克兰宣布对加拿大实施经济制裁发生于霍尔木兹海峡\n\n2023-09-18 01:44:00，乌克兰宣布对加拿大实施经济制裁。据当地媒体报道，冲突造成56人死亡、0人受伤。','paste',NULL,102,'2026-06-01 13:41:27'),(50,'阿联酋在柏林部署新型防空系统','阿联酋在柏林部署新型防空系统\n\n阿联酋在柏林部署新型防空系统发生于柏林\n\n2025-05-05 01:02:00，阿联酋在柏林部署新型防空系统。据当地媒体报道，冲突造成0人死亡、871人受伤。','paste',NULL,96,'2026-06-01 13:41:27'),(51,'越南海军在华盛顿举行联合演习','越南海军在华盛顿举行联合演习\n\n越南海军在华盛顿举行联合演习发生于华盛顿\n\n2024-08-30 13:48:00，越南海军在华盛顿举行联合演习。据当地媒体报道，冲突造成406人死亡、1402人受伤。','paste',NULL,100,'2026-06-01 13:41:27'),(52,'印度尼西亚在莫斯科建立新的军事基地','印度尼西亚在莫斯科建立新的军事基地\n\n印度尼西亚在莫斯科建立新的军事基地发生于莫斯科\n\n2023-09-09 15:45:00，印度尼西亚在莫斯科建立新的军事基地。据当地媒体报道，冲突造成0人死亡、0人受伤。','paste',NULL,104,'2026-06-01 13:41:27'),(54,'[CMNEE #104] 鉴于一名驻阿富汗美国士兵在训练中因XM25式25毫米半自动榴弹发射器出现故障而受伤，美国陆军已经撤回其投放到阿富汗的XM25榴弹发射器样枪及其配用的空爆弹。  ...','鉴于一名驻阿富汗美国士兵在训练中因XM25式25毫米半自动榴弹发射器出现故障而受伤，美国陆军已经撤回其投放到阿富汗的XM25榴弹发射器样枪及其配用的空爆弹。       2013年1月，美国陆军将第二批XM25半自动榴弹发射器样枪及其空爆弹投放到阿富汗进行前方作战评估，第一批5具XM25榴弹发射器自2010年11月～2012年4月部署至阿富汗。美国陆军发言人称，在2013年2月进行的实弹射击试验中，一具XM25半自动榴弹发射器因供弹过程出现故障而导致底火过早地为25毫米空爆榴弹点火，尽管手工制成的空爆弹的空爆战斗部没有起爆，但士兵确实受伤，且该枪无法使用，训练立即停止。事故发生后，陆军从阿富汗撤回了所有的XM25半自动榴弹发射器样枪及其弹药，以便调查事故根源和总结改进方案。陆军已经终止了XM25榴弹发射器的野外试验，旨在进一步制定改进方案，确保武器安全。一旦查清事故原因并提出改进方案，美国陆军将决定该武器何时再次投入使用。同时，XM25半自动榴弹发射器的工程与制造研发阶段工作继续开展，以便进一步完善和改进武器设计。 ','paste','cmnee_test_104.txt',465,'2026-06-16 13:15:12'),(55,'[CMNEE #116] 台军一直认为潜艇在台澎防卫作战中具有突出的重要性，因此从1972年，就从美国获得海狮艇，即水星一号计划。台海军人员在美国康涅狄格州新伦敦美海军潜艇学校接受训练。...','台军一直认为潜艇在台澎防卫作战中具有突出的重要性，因此从1972年，就从美国获得海狮艇，即水星一号计划。台海军人员在美国康涅狄格州新伦敦美海军潜艇学校接受训练。该艇在1973年4月正式将其移交台海军。1974年10月，第二艘同级常规动力潜艇海豹艇抵达海军左营基地，象征第一阶段海军潜艇战力的整备完成。两艘潜艇均为前六后四的鱼雷舱配置，潜艇水下排水量为2400吨。台海军第二阶段的潜艇战力建构，即海龙号、海虎号艇的剑龙项目计划。台海军在1984年10月赴荷兰参与训练及接舰任务，1987年11月，开始在北大西洋上进行海上试车，隔年2月完成，海虎号艇于1988年6月30日返国，7月4日举行成军典礼；海龙号艇则在1987年12月28日成军。台海军第三阶段潜艇战力则是美方已承诺的售台八艘柴电动力潜艇，台海军方面正在积极争取。但未来情况并不明朗。','paste','cmnee_test_116.txt',370,'2026-06-16 13:15:12'),(56,'[CMNEE #532] 据台湾媒体7月5日报道，日本航空自卫队的搜救队今天上午在宫城县牡鹿町光山的山顶附近发现4日上午结束训练返航途中失踪的两架T4教练机的残骸和3名飞行员的遗体，现正...','据台湾媒体7月5日报道，日本航空自卫队的搜救队今天上午在宫城县牡鹿町光山的山顶附近发现4日上午结束训练返航途中失踪的两架T4教练机的残骸和3名飞行员的遗体，现正进行善后工作并调查失事原因。驻扎于宫城县牡鹿町松岛基地，属于日本航空自卫队第4航空团第11飞行队的6架T4教练机在4日上午结束训练后的返航途中，飞在最后的两架机体编号720和727的教练机在离基地约25公里处突然几乎同时从雷达上消失并失去联络。机上3名飞行员都有3000小时以上的飞行纪录。日本航空自卫队和警方昨天上午在海上和山区联合展开救援工作，但由于浓雾导致救援困难。今天上午在雷雨中继续搜索，航空自卫队员根据教练机最后发出的求救信号，于今天上午9点前在光山山顶附近发现散落的两架飞机的残骸和飞行员的遗体，并根据现场的证件，确认是失踪的3名飞行员。可搭乘两人的T4喷气教练机是于1988年开始配备于日本航空自卫队的，5年前开始作为松岛基地所属飞行队的专用教练机，该飞行队的主要任务是表演飞行编队特技，但不时发生意外，以前在静冈县滨松基地外海就曾发生过坠机事件。','paste','cmnee_test_532.txt',462,'2026-06-16 13:15:12'),(57,'[CMNEE #233] 中新网1月13日电 据日媒报道，当地时间12月晚上，日本防卫大臣河野太郎从日本出发前往美国。此访，河野将与美防长埃斯珀就中东局势等问题进行会谈。据报道，河野此次...','中新网1月13日电 据日媒报道，当地时间12月晚上，日本防卫大臣河野太郎从日本出发前往美国。此访，河野将与美防长埃斯珀就中东局势等问题进行会谈。据报道，河野此次访美将为期五天，他首先会前往美国夏威夷视察美军宙斯盾反导系统设施，在那之后，河野将前往美国首都华盛顿与美防长埃斯珀进行会谈。报道称，双方预计将就持续紧张的中东局势以及日本向中东派遣的自卫队与美军如何展开合作等问题交换意见。当地时间1月3日，美军狙杀伊朗高级将领苏莱曼尼；8日，伊朗向美军驻伊拉克基地发射导弹进行报复，中东局势骤然升级。不过之后，美伊双方都表示不希望局势升级。日本防卫大臣河野太郎于日本时间1月10日下午，正式发布命令，派遣自卫队赴中东执行任务。据悉，此次任务编队由一艘护卫舰和两架预警机组成。责编：蒋莉蓉','paste','cmnee_test_233.txt',340,'2026-06-16 13:15:12'),(58,'[CMNEE #797] 印度海军艇员正在俄罗斯阿库拉级K-152攻击型核潜艇上进行训练。该潜艇即将租借给印度，租期10年。 印度海军发言人表示，攻击型核潜艇还没有正式移交给印度。该潜艇...','印度海军艇员正在俄罗斯阿库拉级K-152攻击型核潜艇上进行训练。该潜艇即将租借给印度，租期10年。 印度海军发言人表示，攻击型核潜艇还没有正式移交给印度。该潜艇将由这些正在艇上训练的艇员暂时地带回印度。 该潜艇将以6．5亿至7亿美元的价格租借给印度，并将以印度东海岸Rambilli在建的专用设施作为基地。 印度海军表示排水量12000吨，更名为查拉克号的攻击型核潜艇，可于年底加入印度海军。 攻击型核潜艇最初计划于2009年8月移交给印度海军。然而，该潜艇在2008年11月份的日本海海试期间发生事故，造成包括水手和技术人员在内的共20人死亡，21人受伤，并因此而导致该潜艇移交推迟。该事故是由于潜艇消防系统氟利昂泄漏引起的。 该攻击型核潜艇随后于2009年12月加入俄罗斯海军，为用户进行海试。海试现已完成。 该艘攻击型核潜艇的租借将使印度成为继美、英、俄、法、中5国之后，第六个拥有核潜艇的国家。 作为秘密协议的一部分，印度海军于2004年1月签订了两艘阿库拉级核潜艇的租借合同，但是最终决定只租借1艘。','paste','cmnee_test_797.txt',455,'2026-06-16 13:15:12'),(59,'[CMNEE #887] 美国洛克希德・马丁公司训练与后勤分部近日与美国陆军仿真、训练与测量项目执行办公室签订了一份合同，为可测量多集成激光模拟作战系统提供肩射弹药仿真组件，用于战术作战...','美国洛克希德・马丁公司训练与后勤分部近日与美国陆军仿真、训练与测量项目执行办公室签订了一份合同，为可测量多集成激光模拟作战系统提供肩射弹药仿真组件，用于战术作战训练。各种弹药的仿真组件可根据用户要求定制，模拟特定武器的弹道，且体积小巧，可集成到任何武器中。根据合同要求，洛克希德・马丁公司训练与后勤分部将提供1400套20种不同的模拟组件。       另外，雷声公司也演示了新一代肩射多用途突击武器II的模拟训练器。该模拟器与肩射多用途突击武器II的外观相同，集成了美军VBS-2现役制式虚拟环境模拟系统。肩射多用途突击武器II模拟训练器的部署时间尚不能确定，因为肩射多用途突击武器II本身要到2012年以后才能部署。另外，雷声公司还自主研发了标枪反坦克导弹的新模拟训练器，同样也集成了VBS-2虚拟环境模拟系统。 ','paste','cmnee_test_887.txt',359,'2026-06-16 13:15:12'),(60,'[CMNEE #1641] 资料图：俄罗斯计划租借给印度的海豹号核潜艇 　　中新网9月23日电 俄罗斯哈巴罗夫斯克边疆区行政长官维亚切斯拉夫·什波尔特23日透露，在去年11月试航期间发生事...','资料图：俄罗斯计划租借给印度的海豹号核潜艇 　　中新网9月23日电 俄罗斯哈巴罗夫斯克边疆区行政长官维亚切斯拉夫·什波尔特23日透露，在去年11月试航期间发生事故并造成20人死亡的俄罗斯海豹号核潜艇已成功完成第三阶段试航。　　据俄新网报道，海豹号核潜艇在阿穆尔河畔共青城制造，目前尚未编入俄罗斯海军。2008年11月8日工厂试航期间这艘核潜艇在日本海发生事故。由于消防系统故障导致氟利昂泄露到船舱，造成20人死亡，还有21人中毒住院。当时船上共有208人。　　什波尔特说：潜艇目前处在良好的准备状态，并且我确信将按时交付使用。　　据他称，在10月上旬将向工厂投入19亿卢布用于海豹号在事故后的修复工作。这些资金能帮助工厂解决工资和与承包商结算的问题。什波尔特解释说。　　此前有消息称，潜艇在结束试航后将转交给印度海军。','paste','cmnee_test_1641.txt',359,'2026-06-16 13:15:12'),(61,'[CMNEE #1752] 苏联第一艘核潜艇K-3号，后来被命名为列宁共青团号，于1958年12月17日交付给苏联海军。 苏联第一艘核潜艇于1955年在北德文斯克船厂开始建造，1957年8...','苏联第一艘核潜艇K-3号，后来被命名为列宁共青团号，于1958年12月17日交付给苏联海军。 苏联第一艘核潜艇于1955年在北德文斯克船厂开始建造，1957年8月下水，同年晚些时候核潜艇上的核反应堆开始装入核燃料。该艇与1959年在俄罗斯北方舰队服役，1962年被命名为列宁共青团号。 北德文斯克船厂主任Nikolay Kailistratov对Pravda Sever新闻报称：我们的列宁共青团号在保护和平的过程中起着至关重要的作用。美国已经有核潜艇，K-3号使得两个超级大国机会对等。 1967年9月，列宁共青团号在挪威海域艇上发生了火灾，导致39名艇员死亡。该艇于1991年退役，并准备进入博物馆。为了建造K-3，在北德文斯克船厂成立了一个新的部门――42号部门。直到现在，该部门仍然是国家最机密的部门。在这里，建造了俄罗斯第一艘核动力潜艇、第一艘大潜深潜艇以及第一艘钛合金潜艇。','paste','cmnee_test_1752.txt',393,'2026-06-16 13:15:12'),(62,'[CMNEE #380] 6月6日，巴西总统Jair Bolsonaro和阿根廷总统Mauricio Macro会晤后，巴西海军同意将两艘Tupi级常规潜艇卖给阿根廷。     该交易共...','6月6日，巴西总统Jair Bolsonaro和阿根廷总统Mauricio Macro会晤后，巴西海军同意将两艘Tupi级常规潜艇卖给阿根廷。     该交易共包括四艘209型潜艇。前两艘将在2019年间移交，随后在阿根廷的Tandanor造船厂进行一些简单维修，并于2020年投入使用。另外两艘交付时间尚不明确。     巴西海军的四艘Tupi级潜艇于1989年至1999年期间服役，未来将被新采购的四艘Tonelero级潜艇取代。     目前，阿根廷海军已无潜艇可用。2017年11月15日，阿根廷海军TR1700型潜艇圣胡安号发生事故，导致沉没，随后另一艘TR1700型潜艇圣克鲁斯号也停止服役，将进行事故测试。测试工作于2019年2月重新开始，该艇或将于2021年重新投入使用。此外，阿根廷海军还拥有一艘209型1200吨级潜艇萨尔塔号，该艇1974年服役并已达到使用寿命，2017年以来一直没有再服役。 ','paste','cmnee_test_380.txt',408,'2026-06-16 13:15:12'),(63,'[CMNEE #531] 美国将首次派遣核潜艇参加2000年美国与泰国、文莱、新加坡、马来西亚、菲律宾和印尼等国举行的克拉特军事演习。美泰2000年克拉特军事演习开始后，一艘目前位于澳大...','美国将首次派遣核潜艇参加2000年美国与泰国、文莱、新加坡、马来西亚、菲律宾和印尼等国举行的克拉特军事演习。美泰2000年克拉特军事演习开始后，一艘目前位于澳大利亚核潜艇将两天内将抵达泰国参加演习。这次演习是以防卫为目的，因此着重反潜艇演练。今年克拉特军事演习的目的在保证使美军与东南亚各国军队有面对世界任何挑战的准备，以海军和陆战队行动为演练，动用的舰艇和部队包括护航驱逐舰、陆战队使用的水陆两用舰艇、扫雷艇、救难部队、军需品专家、海豹部队、海蜂部队、海岸防卫人员和医疗专业人员等。美方动员一千八百名官兵参加这项演习。泰国动用四艘军舰、六架直升机、特战队、工程部队、水陆两栖部队、海军流动医疗队和救难小组等。在泰国自本月三日起长达十天演习中，头七天在港口演练，十日起三天在海上演习，十四日最后一天是人道援助，美军将前往罗勇省和春武里省泰国村进行医疗服务，并在罗通省一所学校建造多目的楼房。 ','paste','cmnee_test_531.txt',396,'2026-06-16 13:15:12'),(64,'[CMNEE #772] 波兰空军打算在阿富汗Ghazni省部署一架空客C-295军用战术运输机，这一决定是华沙同意作为以北约为首的国际安全援助部队的一员扩大在阿富汗的军事存在之后做出的...','波兰空军打算在阿富汗Ghazni省部署一架空客C-295军用战术运输机，这一决定是华沙同意作为以北约为首的国际安全援助部队的一员扩大在阿富汗的军事存在之后做出的。派往阿富汗的C-295运输机将从波兰空军第十三运输机中队抽调，用于执行运输、空投、医疗救援任务，涉及20名飞行员和技术保障人员。波兰空军运输机队伍在4月26日随着该国第二架洛•马C-130E的交付而壮大，技术交接工作完成后配属第十四运输机队。波兰空军正在继续对今年初发生的C-130E在阿富汗遭遇轻微事故造成损伤的原因进行调查。此外，波兰空军还从第一战术空军中队抽调了四架米格-29派驻立陶宛Siauliai空军基地，接替法国空军的幻影2000战机参与北约驻波罗的海国家的空中警戒任务，预计将于8月31日形成快速反应能力。华沙原计划派遣F-16执行这一任务，但该国空军作战司令部司令Slawomir Dygnatowsk将军称该方案在进行经济性评估后被放弃。','paste','cmnee_test_772.txt',410,'2026-06-16 13:15:12'),(65,'[CMNEE #801] 意大利海军10月11日表示，3架AW-101型直升机将在10月13日抵达阿富汗地区开始为期12个月的任务周期。 这些直升机将由美国空军的C-17运输机运抵阿富汗...','意大利海军10月11日表示，3架AW-101型直升机将在10月13日抵达阿富汗地区开始为期12个月的任务周期。 这些直升机将由美国空军的C-17运输机运抵阿富汗，将安置在阿富汗赫拉特地区，未来将负责执行监视、巡逻、护卫保障、威慑以及医疗救援等任务。AW-101型直升机装备有夜视及自我保护系统，随飞机一起抵达阿富汗的还有67名作战人员及维护人员。此前，意大利海军已经向阿富汗地区部署了AB212型直升机，同空军的AB214型飞机进行协同作战。 10月9日，阿富汗法拉赫地区发生的一起路边炸弹爆炸事故中，4名意大利士兵在山猫装甲车中丧生。 意大利国防部部长拉鲁萨回应这一事件称，他将在本周与意大利国会进行协商，以决定是否允许在阿富汗地区执行任务的意大利飞机携带炸弹。目前在阿富汗地区执行作战任务的意大利AMX型战斗机仅允许执行监视任务。','paste','cmnee_test_801.txt',367,'2026-06-16 13:15:12'),(66,'[CMNEE #907] 雷神公司完成了标准导弹-3Block IB的首次成功飞行试验，该导弹是美国当局的分阶段适应办法第二阶段的基石。这是雷神公司SM-3项目第20次成功拦截。 雷神公...','雷神公司完成了标准导弹-3Block IB的首次成功飞行试验，该导弹是美国当局的分阶段适应办法第二阶段的基石。这是雷神公司SM-3项目第20次成功拦截。 雷神公司导弹系统主管说：SM-3的下一代改型对于美国及其盟国的弹道导弹防御至关重要，它能击败当今世界各地出现的更为复杂的威胁。 试验中，靶弹从太平洋导弹靶场发射，美国伊利湖号军舰上的SPY-1雷达获取并跟踪了目标。舰上工作人员随后发射了一枚SM-3 Block IB导弹。飞行中，导弹动能弹头上的双色红外寻的器捕获了目标，并实施跟踪，直至拦截。 雷神公司的SM-3 Block IB导弹是基于非常成功的SM-3 Block IA，目前SM-3 Block IA已经部署，作为PAA第一阶段的组成部分。 雷神导弹系统部门防空反导系统生产线负责人称，雷神公司已经提前交付了超过130枚SM-3 Block IA，并将成本控制在预期范围之内。公司将在2015年前交付SM-3 Block IB导弹，用于海上和岸上部署。','paste','cmnee_test_907.txt',433,'2026-06-16 13:15:12'),(67,'[CMNEE #1606] 法国DCNS船厂为俄罗斯海军建造的两艘西北风级两栖舰中的第一艘符拉迪沃斯托克号已于本周二下水，并将于明年3月开始海试。 DCNS项目经理表示，该艘两栖舰在交付俄...','法国DCNS船厂为俄罗斯海军建造的两艘西北风级两栖舰中的第一艘符拉迪沃斯托克号已于本周二下水，并将于明年3月开始海试。 DCNS项目经理表示，该艘两栖舰在交付俄罗斯的时候不会装备武器，但会配备法国建造的登陆装置。按照建造计划，法国DCNS船厂在完成船体建造以后会将该舰交付俄罗斯北方造船厂，北方造船厂负责为该舰安装俄制武器系统，预计该舰将于2014年11月交付俄罗斯海军。 俄罗斯与法国于2011年6月签订了两艘西北风级两栖舰的建造合同，价值12亿欧元。该级舰的第二艘塞瓦斯托波尔号计划在2014年10月下水。 俄罗斯国防采购官员表示，俄罗斯是否决定采购第三和第四艘西北风级两栖舰将完全取决于第一艘舰的测试情况。 西北风级两栖舰能搭载16架直升机、4艘登陆艇、70量装甲车以及450名士兵，其空军支队包括8架52K攻击直升机和8架卡-29/31直升机。','paste','cmnee_test_1606.txt',376,'2026-06-16 13:15:12'),(68,'[CMNEE #1646] 【美国海军学院新闻网2020年3月17日报道】美国海军 阿利•伯克级驱逐舰德尔伯特•布莱克号上周在墨西哥湾完成验收试验，预计今年晚些时候交付并服役。德尔伯特•布...','【美国海军学院新闻网2020年3月17日报道】美国海军 阿利•伯克级驱逐舰德尔伯特•布莱克号上周在墨西哥湾完成验收试验，预计今年晚些时候交付并服役。德尔伯特•布莱克号驱逐舰2017年9月下水，原定2019年服役，但在一年前受损，当时一艘名为鹰号的重型运输船正在运载一座浮船坞进入帕斯卡古拉的英格尔斯造船公司码头，撞上了正在对未完工的德尔伯特•布莱克号输送电力的一艘驳船，导致该驳船与德尔伯特•布莱克号发生碰撞，造成德尔伯特•布莱克号建造工作延迟。德尔伯特•布莱克号驱逐舰配备了宙斯盾基线9作战系统，与更早的阿利•伯克级驱逐舰相比，其计算能力得到提高，升级后的雷达可与其他舰船和飞机连接以创建战场的综合图景，可同时执行传统的空战任务和弹道导弹防御任务。而未来的首艘阿利•伯克Flight III型驱逐舰杰克•卢卡斯号将首次配备宙斯盾基线10系统。','paste','cmnee_test_1646.txt',372,'2026-06-16 13:15:12'),(69,'[CMNEE #1677] 为了为替代诺格公司C-2灰狗运输机做准备，美国海军在6月12日从海军陆战队第一作战测试与评估中队接收了一架波音公司的MV-22鱼鹰倾转旋翼机，并计划在尼米兹级航...','为了为替代诺格公司C-2灰狗运输机做准备，美国海军在6月12日从海军陆战队第一作战测试与评估中队接收了一架波音公司的MV-22鱼鹰倾转旋翼机，并计划在尼米兹级航母上开展飞行评估。 这些评估姜维我们的机组成员提供在航母上着陆的飞行经验，中队官员称，我们的飞行员将适应不同的作战流程，也能使卡尔・文森号上的舰载机飞行员熟悉驾驶倾转旋翼机。 海军已将V-22列为其下一代航母舰载运输机。但海军不会启动新的记录项目来采购额外的鱼鹰改进型，而是注资当前海军陆战队的MV-22项目，最终将44架。新的改进型可携带更多燃料，航程更远，并配备了高频无线电和公共广播系统。改进型鱼鹰计划从2020年开始交付。 目前采购的这架MV-22将在卡尔・文森号航母上执行起飞和着陆训练，机组成员认为这是一次难得的学习驾驶鱼鹰的经历，我们正逐步淘汰C-2，并开始评估测试V-22。这是我们的船员首次接触新型飞机。','paste','cmnee_test_1677.txt',391,'2026-06-16 13:15:12'),(70,'[CMNEE #48] 俄罗斯周二启动了一部最先进的反导雷达系统，以应对美国等西方国家在欧洲部署导弹防御系统的计划，该反导雷达位于波罗的海海岸，北约成员国波兰和立陶宛之间，监视范围达6...','俄罗斯周二启动了一部最先进的反导雷达系统，以应对美国等西方国家在欧洲部署导弹防御系统的计划，该反导雷达位于波罗的海海岸，北约成员国波兰和立陶宛之间，监视范围达6000公里。 俄罗斯总统德米特里・梅德韦杰夫表示，他坚持上周要采取行动对抗以美国为首的北约成员国部署导弹防御系统对莫斯科核威慑造成的威胁，这是俄罗斯发出的第一个信号，以表明他们足以应对欧洲导弹防御对他们战略核力量的威胁。反导雷达启动仪式在俄罗斯波罗的海海岸的加里宁格勒举行的，仪式过后，梅德韦杰夫对最高军事指挥官做出相关指示。整个2011年，沃罗涅日-DM雷达站一直在进行该雷达的测试。据俄罗斯文传通讯社报导，在此期间雷达没有出现技术故障。沃罗涅日-DM雷达站的有效监测范围为6000公里，能够和莫斯科的导弹防御系统协同工作。梅德韦杰夫在电视讲话中说：如果部署雷达的措施不够，正如我在11月23日所说，俄罗斯将继续采取其他防御手段。','paste','cmnee_test_48.txt',396,'2026-06-16 13:15:12'),(71,'[CMNEE #69] 美国海军陆战队3日出动攻击机轰炸了阿富汗南部的目标，这是美国自10月7日对阿富汗开战以来美国海军陆战队攻击机首次对阿进行打击。美国军事官员称，集结在印度洋的美国...','美国海军陆战队3日出动攻击机轰炸了阿富汗南部的目标，这是美国自10月7日对阿富汗开战以来美国海军陆战队攻击机首次对阿进行打击。美国军事官员称，集结在印度洋的美国军舰3日派遣鹞式战斗机向阿富汗南部投掷炸弹。这是美国对阿富汗实施军事打击以来，美国海军首次使用鹞式战斗机对阿富汗境内的军事目标实施轰炸。3日清晨，隶属美国海军第15远征队的4架AV-8B鹞式战斗机从停泊在阿拉伯海的佩雷利乌号两栖攻击舰上起飞，向北飞往阿富汗，途中由一架C-130大力神运输机补充燃料。起航不久，一架战斗机因通讯系统问题而被迫返航。其余3架战机进入阿富汗境内后，分别向阿南部塔利班军事目标投下4枚500磅重的无制导炸弹。4小时后，3架战斗机安全返回舰上。佩雷利乌号战舰于9月28日抵达北阿拉伯海，是美国海军远征部队某舰群的旗舰。该舰群包括3艘战舰：佩雷利乌号两栖攻击舰、康斯托克号登陆舰和迪比克号登陆舰。舰上共有2200名海军陆战队士兵和1900名海员。该舰群还配备了一支空军部队，装备有25架直升机和6架鹞式战斗机。这些鹞式战斗机无须弹射器，便可以在飞行甲板上垂直起落。','paste','cmnee_test_69.txt',473,'2026-06-16 13:15:12'),(72,'[CMNEE #733] BAE系统公司研制的 猎迷MRA4侦察机的首架生产型样机于9月10日完成了首次试飞，这距该机被英国皇家空军选中已有13年之久。  PA4号飞机的首飞是在BAE系...','BAE系统公司研制的 猎迷MRA4侦察机的首架生产型样机于9月10日完成了首次试飞，这距该机被英国皇家空军选中已有13年之久。  PA4号飞机的首飞是在BAE系统公司的Woodford机场进行的，该机起飞后共持续飞行了1小时40分钟，随后在Norwich机场着陆，在那儿该机将喷绘上英国空军的涂装。今后PA4号飞机还将飞至BAE公司位于兰开夏郡的Warton机场，以进行交付使用前的进一步飞行测试。  根据合同，BAE公司将在年底前完成英国空军订购的9架猎迷MRA4侦察机中的首批4架飞机的交付。按计划，这4架飞机将部署在苏格兰的Kinloss空军基地，并于2010年12月具备初始作战能力。而英国空军现役的猎迷MR2飞机将在2011年3月31日前停止使用。','paste','cmnee_test_733.txt',329,'2026-06-16 13:15:12'),(73,'[CMNEE #748] 11月20日，在苏霍伊控股公司下属的阿穆尔共青城航空生产联合体举行了向俄罗斯空军移交最后一批改进升级苏-27SM歼击机的仪式。企业领导、俄罗斯国防部军事代表处的...','11月20日，在苏霍伊控股公司下属的阿穆尔共青城航空生产联合体举行了向俄罗斯空军移交最后一批改进升级苏-27SM歼击机的仪式。企业领导、俄罗斯国防部军事代表处的代表、接装歼击机的航空兵团指挥员出席了飞机交接仪式。  在为俄罗斯国防部改造飞机计划框架内，阿穆尔共青城航空生产联合体对俄罗斯空军装备的苏-27S前线歼击机进行了维修和改造。经现代化改造后飞机拥有了新的性能，其作战效率大大提高。除此之外，阿穆尔共青城航空生产联合体还在对俄罗斯空军的苏-27S歼击机进行检测和恢复；对俄罗斯海军的苏-33歼击机进行中等维修和补充装备；展开了履行今年8月签订的在2015年前向俄罗斯国防部供应48架多功能超机动苏-35歼击机国家合同的工作；并为外国订购商生产双座苏-30MK2和单座苏-27SKM多用途歼击机；该企业还在实施苏霍伊公司制造第五代战机的计划，及在组装中程干线客机苏霍伊超级喷气式-100。','paste','cmnee_test_748.txt',396,'2026-06-16 13:15:12'),(74,'[CMNEE #1238] 美国海军的第一艘濒海战斗舰将被命名为自由号。          洛克希德・马丁公司目前正在建造第一艘濒海战斗舰。今年6月，洛克希德・马丁公司和马里内特海事公司将...','美国海军的第一艘濒海战斗舰将被命名为自由号。          洛克希德・马丁公司目前正在建造第一艘濒海战斗舰。今年6月，洛克希德・马丁公司和马里内特海事公司将为自由号举行一次龙骨铺设仪式。到2006年上半年，自由号濒海战斗舰将完成建造和海上测试工作。       现有洛克希德・马丁公司和通用动力公司在竞标濒海战斗舰最终方案。洛克希德・马丁公司提出的方案为半滑行单体船设计，而通用动力公司提出的方案则为三体船设计。       濒海战斗舰将可安装一组使命模块，可承担多种使命，包括反潜战和反水雷战。濒海战斗舰也可部署无人机、无人艇和无人水下航行器。       美国海军计划在2035年之前采购至少300艘濒海战斗舰。第一艘濒海战斗舰将在2007年交付给美国海军。','paste','cmnee_test_1238.txt',333,'2026-06-16 13:15:12'),(75,'[CMNEE #1622] 2015年1月23日，排水量20000吨级的磐石号战斗支援舰交付。       磐石级号由台湾国际造船股份有限公司建造，耗资1.3亿美元，于2011年开始建造，...','2015年1月23日，排水量20000吨级的磐石号战斗支援舰交付。       磐石级号由台湾国际造船股份有限公司建造，耗资1.3亿美元，于2011年开始建造，2013年下水。       根据台湾国防部表示，磐石级是多功能型舰艇，将用于运输、海事救援、人道主义救援。海军表示将于本月开始人员训练，舰艇将于3月份进入服役状态。       磐石级长196米，宽25.2米，满载排水量20000吨，舰员165人，续航力8000海里，在该舰服役前，台湾海军仅拥有一艘武夷号补给舰，该舰1990年服役。       该舰将装备1门76毫米奥托・梅拉腊舰炮，2门雷声公司的密集阵近防武器，2门莱茵金属公司35毫米舰炮和2门30毫米机炮。武夷号补给舰装备博福斯40毫米/70倍径防空加农炮和2 部T-75型20毫米舰炮。','paste','cmnee_test_1622.txt',355,'2026-06-16 13:15:12'),(76,'[CMNEE #1642] 俄罗斯发生事故的猎豹号核潜艇 　　中新社莫斯科十一月十三日电 俄罗斯联邦总检察院侦查委员会发言人马尔金十二日表示，该委员会军事侦查局将继续对海豹号核潜艇事故嫌疑...','俄罗斯发生事故的猎豹号核潜艇 　　中新社莫斯科十一月十三日电 俄罗斯联邦总检察院侦查委员会发言人马尔金十二日表示，该委员会军事侦查局将继续对海豹号核潜艇事故嫌疑人立案侦查。　　这位发言人同时公布了核潜艇八日发生事故的原因，尚未装备俄海军的海豹号核潜艇八日在日本海水域潜水试航时，潜艇指挥部一名水兵毫无理由地擅自启动了灭火系统。灭火系统向一号和二号舱室释放了大量氟利昂，导致舱内三名军人和十七名潜艇生产企业员工共二十人死亡，二十一人受伤。这名水兵已向侦方提供了擅自启动灭火系统的证词。　　但有俄罗斯媒体援引该潜艇一名军官的话说，被指控的同事是一名服役多年的经验丰富的艇员，我们不相信他会专门或无意打开灭火系统，我和他自二00三年就一起服役，他并非头一次在舰艇上服役。　　据悉，事故潜艇上当时共载有二百零八人，其中包括八十一名军人，其他人是阿穆尔造船厂及协作企业的专家和工作人员。','paste','cmnee_test_1642.txt',388,'2026-06-16 13:15:12'),(77,'[CMNEE #1737] 2002年10月30日，法国海军戴高乐航空母舰在地中海首次试射了MBDA公司的海军型紫苑-15区域防御系统。 法国海军官员透露，该导弹从西瓦尔垂直发射系统中发射...','2002年10月30日，法国海军戴高乐航空母舰在地中海首次试射了MBDA公司的海军型紫苑-15区域防御系统。 法国海军官员透露，该导弹从西瓦尔垂直发射系统中发射，在飞行8.8秒后，拦截了距离航母6.1千米外的目标。来袭目标被彻底摧毁。这是紫苑-15导弹首次从作战平台上射击，并构成了验证戴高乐航母舰对空反导系统的最终平台。戴高乐航母装备用于发射紫苑-15导弹的8联装西瓦尔垂直发射系统、阿拉贝尔雷达及火控系统。2001年12月，在戴高乐航母首次起航前往阿拉伯海支援美国为首的对付阿富汗战争之前，紫苑-15系统首次安装在航空母舰上。除戴高乐航母之外，该导弹还将装备法国－意大利的地平线防空护卫舰和英国皇家海军45型驱逐舰。此外，沙特也已经选定紫苑－15装备其Sawarii-II护卫舰。  紫苑－15导弹','paste','cmnee_test_1737.txt',351,'2026-06-16 13:15:12'),(78,'[CMNEE #1835] 今天在萨伯公司Linköping工厂举行的一个瑞典同泰国的合同签署仪式上，萨伯公布了其为泰国客户定制的综合防空系统。皇家泰国空军总司令、瑞典防务产品管理局主管以...','今天在萨伯公司Linköping工厂举行的一个瑞典同泰国的合同签署仪式上，萨伯公布了其为泰国客户定制的综合防空系统。皇家泰国空军总司令、瑞典防务产品管理局主管以及萨伯公司首席执行官等众多贵宾参加了这一仪式。 皇家泰国空军即将获得鹰狮C/D、爱立眼机载早期预警系统和一种包括数据链通讯的指挥和控制C2系统。同主要瞄准于技术转让的双边合作相结合，这些装备将为泰国提供一种基于先进网络的防御系统基础。 皇家泰国空军将在2011年初接收6架最新型鹰狮C/D多用途战斗机。而两架萨伯340飞机将于2010年12月交付。一套包括三套陆基无线电站设备的指挥和控制C2系统将于2011年3月交付。 首架泰国鹰狮战斗机在2009年9月完成了首飞。而泰国的飞行员和与飞机维护和支持相关的技术人员已经开始在瑞典的武装部队技术学校接受培训。','paste','cmnee_test_1835.txt',358,'2026-06-16 13:15:12'),(79,'[CMNEE #1881] 本周一，    韩国  国防采办计划管理局透露，韩国已经在西部海域的军舰上部署了先进的海基雷达系统，以便更好的监视朝鲜方面的活动。       在2010年11...','本周一，    韩国  国防采办计划管理局透露，韩国已经在西部海域的军舰上部署了先进的海基雷达系统，以便更好的监视朝鲜方面的活动。       在2010年11月，朝鲜军队炮击延坪岛导致4名韩国军人死亡后，STX发动机公司花费了51亿韩元开发新型海基雷达系统，以取代旧的系统。       在8个月前，一艘韩国军舰还在该区域失事，导致了46名军人死亡。韩国当局指责朝鲜发射鱼雷击沉了该军舰，但是朝鲜方面予以否认。       新型的雷达系统具有先进的探测能力，能够探测到25公里以外的舰艇。并且雷达能够与基于军事卫星的海军战术数据系统相连接，以方便舰艇间的通信。','paste','cmnee_test_1881.txt',281,'2026-06-16 13:15:12'),(80,'[CMNEE #2871] 俄罗斯将一艘新建的核动力潜艇交给了印度，租借期为10年。这艘阿库拉级Nerpa号核潜艇在印度船员的指挥下离开了俄罗斯太平洋海岸，驶往印度。这艘核潜艇于1993年...','俄罗斯将一艘新建的核动力潜艇交给了印度，租借期为10年。这艘阿库拉级Nerpa号核潜艇在印度船员的指挥下离开了俄罗斯太平洋海岸，驶往印度。这艘核潜艇于1993年开始建造，由于资金短缺，2008年才下水并开始进行海试。在2008年11 月的海试当中，潜艇的灭火系统出现故障，有20人因吸入有毒气体死亡。 俄新社引用消息来源称，今年，Nerpa号核潜艇进行了一次去往堪察加半岛的航行，随后造船厂和有关专家将其水下噪声降低到最低。潜艇在深水中的适航性也得到了改进。 据位于莫斯科的国防智库机构战略与技术分析中心的估计，俄罗斯2009年的武器出口有四分之一都去往了印度。','paste','cmnee_test_2871.txt',281,'2026-06-16 13:15:12'),(81,'[CMNEE #2969] 英国前卫级核潜艇。 法国凯旋级战略核潜艇。 　　国际在线报道：英国国防部16日证实，英国和法国的两艘核潜艇本月初确实在大西洋发生了相撞事故。　　英国第一海务大臣...','英国前卫级核潜艇。 法国凯旋级战略核潜艇。 　　国际在线报道：英国国防部16日证实，英国和法国的两艘核潜艇本月初确实在大西洋发生了相撞事故。　　英国第一海务大臣乔纳森·班德表示，英国皇家海军的前卫号核潜艇和法国海军的凯旋号核潜艇本月初在大西洋中部海域相撞，两艘核潜艇均严重受损，但未有人员伤亡。该官员还表示，两艘核潜艇是在水下低速行进过程中相撞的，相撞事故并未造成核安全问题。目前前卫号已经被拖回位于苏格兰的基地。　　此前，英国国防部拒绝证实这一事故，称对此发表评论，有悖不就核潜艇活动情况发表评论的政策。 已有_COUNT_位网友发表评论 我要评论　　相关阅读：　　英国海军隐瞒核潜艇严重核泄露事故遭调查　　英国核潜艇放射性液体泄漏流入附近海域　　英国国防部公布去年不懈号核潜艇事故原因　　英国壮丽号核潜艇与岩石相撞9名士兵受伤　　法国第四艘凯旋级核潜艇下水 可配M51洲际导弹　　相关专题：英法核潜艇大西洋相撞','paste','cmnee_test_2969.txt',407,'2026-06-16 13:15:12'),(82,'[CMNEE #46] 本周美国《时代》杂志披露：纳米蜂鸟无人机被誉为美国年度50大发明之一。该无人机外形酷似蜂鸟，重量不及一块5号电池，通过快速拍动翅膀，做盘旋、俯冲、爬升或快速前飞...','本周美国《时代》杂志披露：纳米蜂鸟无人机被誉为美国年度50大发明之一。该无人机外形酷似蜂鸟，重量不及一块5号电池，通过快速拍动翅膀，做盘旋、俯冲、爬升或快速前飞等动作。无人机载摄像头能够向操作员实时传递影像资料，有助于作战人员在安全距离以外关注潜在的战场威胁。 美国已经在阿富汗部署了小型WASP、捕食者、全球鹰等数百架无人机。这个在以前看似无法想象的场景，如今已成家常便饭。过去两年里，空军已经训练了大量的飞行员来控制无人机。 今年2月17日，美国国防部预研局和航空环境公司首次对外公布了纳米蜂鸟无人机的有关研制情况。自2006年以来，航空环境公司在DARPA支持下，花费了近5年时间研制出这种超微型无人机。目前，纳米蜂鸟还处在原型机测试阶段，未来可能会将其应用在军队救援和监控任务中。','paste','cmnee_test_46.txt',344,'2026-06-16 13:15:12'),(83,'[CMNEE #174] 近日，Leidos公司成功完成了海上自治系统原型的首次自导航行。 该系统设计用于美国国防部先进研究项目局的反潜持续追踪无人艇艇计划，在35nm航行期间安装在42...','近日，Leidos公司成功完成了海上自治系统原型的首次自导航行。 该系统设计用于美国国防部先进研究项目局的反潜持续追踪无人艇艇计划，在35nm航行期间安装在42英尺长的工作艇上。 该艇用作代理艇只对原型ACTUV的传感器、调遣和任务功能进行测试，成功地航行经过海湾沿岸航道复杂的近海环境，没有任何预先规划的中间站或人为干预。 该艇采用自治系统控制，并且将该区域的航海图加载至存储器内，还装配了来自商用现货雷达的输入。 该系统满足所有自治功能要求，使艇能避开障碍物、浮标、陆地、浅水区和区域内其他艇只。 Leidos公司目前正在继续制造Sea Hunter，这是美国俄勒冈州克拉克马斯第一艘ACTUV原型艇。 Sea Hunter今年推出之后，将在哥伦比亚河进行试验。 DARPA的ACTUV计划最初用于反潜作战任务，旨在开发独立部署的无人海军舰艇，将在稀疏远程监督控制下运行，并遵守海洋避碰规章，即COLREGS。','paste','cmnee_test_174.txt',407,'2026-06-16 13:15:12'),(84,'[CMNEE #473] 据新浪网3月17日报道，美国海军的一位官员15日在国防部举行的记者招待会上说，美海军的下一代战斗机F/A-18E/F超级大黄蜂已通过试飞，海军计划大批采购这种飞...','据新浪网3月17日报道，美国海军的一位官员15日在国防部举行的记者招待会上说，美海军的下一代战斗机F/A-18E/F超级大黄蜂已通过试飞，海军计划大批采购这种飞机。据这位官员透露，美国军方将在未来10年中耗资450亿美元购买548架F/A-18E/F超级大黄蜂战斗机。他说，海军最近在加利福尼亚州的试飞基地对这种舰载战斗机进行了严格的测试，获得了理想的结果。F/A-18E/F是F/A-18C/D的改进型。这种新型战斗机分为单座和双座，装备了目前最先进的综合航空电子系统和武器，具有超音速巡航、隐身、机动敏捷等特点。与原有的机种相比，改进后的F/A-18续飞时间长、作战半径大、携带武器多。美国海军将用这种飞机替代目前正在使用的F/A-18C/D和F-14战斗机。据悉，波音公司已向美国军方移交了第一批新型超级大黄蜂战斗机。海军计划于2002年将这批飞机装备在林肯号航空母舰上。','paste','cmnee_test_473.txt',389,'2026-06-16 13:15:12'),(85,'[CMNEE #481] 据新华网１月８日报道，美国国防部导弹防御署发言人莱纳尔８日宣布，美军方决定取消定于今年上半年进行的两次导弹拦截试验，原因是发射拦截导弹的新型助推火箭的开发落后于...','据新华网１月８日报道，美国国防部导弹防御署发言人莱纳尔８日宣布，美军方决定取消定于今年上半年进行的两次导弹拦截试验，原因是发射拦截导弹的新型助推火箭的开发落后于原定进程。 莱纳尔对此间新闻界说，导弹防御署今年需要集中精力解决助推火箭的问题，下一次导弹拦截试验将在今年秋季波音公司生产出新型助推火箭后进行。波音公司原计划于２０００年开始对运载导弹拦截器的新型助推火箭进行飞行试验，但由于技术原因而推迟。在２００１年１２月助推火箭发射失败后，波音公司决定重新进行设计，并定于今年秋季完成。 在已进行的８次陆基导弹拦截试验中，美国军方使用改装的民兵号火箭作为替代助推器，但这种助推器的试验效果并不理想。２０００年７月和去年１２月进行的导弹拦截试验都因拦截器未能与助推火箭分离而失败。 美国总统布什于去年１２月１７日下令国防部着手部署导弹防御系统，争取到２００４年９月建立一个初步的导弹防御系统。但不少专家认为，仅从技术上来讲，部署导弹防御系统的时机尚未成熟。导弹防御署主任卡迪什也表示，如果波音公司不能如期制造出合格的助推火箭，整个导弹防御系统的部署将受到影响。','paste','cmnee_test_481.txt',478,'2026-06-16 13:15:12'),(86,'[CMNEE #810] 波兰国防部长波格丹・克利赫18日表示，美国的F-16战斗机和C-130大力神运输机将于2013年部署至波兰。 克利赫称，波兰已经接受了美国在其国土内轮换部署F-...','波兰国防部长波格丹・克利赫18日表示，美国的F-16战斗机和C-130大力神运输机将于2013年部署至波兰。 克利赫称，波兰已经接受了美国在其国土内轮换部署F-16战斗机和大力神运输机及机组人员的请求，他希望从2013年起开始轮换部署。部署方式将类似今年5月份美国开始在波兰部署的爱国者防空导弹系统。 克利赫称，美国在波兰国土上的军事存在，表明在形势需要的情况下，波兰能够得到北约盟国的帮助。 克利赫还宣布，波兰及三个波罗的海国家将于2013年举行北约快速反应部队演习，演练25000人规模的多国部队快速部署，执行危机管理，维稳或共同防务任务。 克利赫还称波兰非常赞同北约新提出的战略概念，这一概念将在11月19~20日举行的里斯本峰会上由28个成员国进行讨论。','paste','cmnee_test_810.txt',331,'2026-06-16 13:15:12'),(87,'[CMNEE #1529] 韩国媒体2017年4月报道，韩国在国防发展局的一个试验场成功试射射程达800千米的新型弹道导弹，其射程能够覆盖朝鲜全境。导弹在试验中满足所有关键性能指标，正常飞...','韩国媒体2017年4月报道，韩国在国防发展局的一个试验场成功试射射程达800千米的新型弹道导弹，其射程能够覆盖朝鲜全境。导弹在试验中满足所有关键性能指标，正常飞行、起爆并命中目标。韩国国防部没有对此次试验予以证实，只是表示正在研制射程800千米，可携带500千克载荷的弹道导弹。韩国政府表示，新弹道导弹目前还处于研制阶段，尚无法确定其具体部署时间，导弹名称将在部署后公布。     据美国方面的信息，朝鲜此次试射的弹道导弹是飞毛腿导弹的增程型，飞行了60千米，但试验没有取得成功。据美国和韩国估计，朝鲜此次试射的弹道导弹与其1月试射的KN-15北极星-2中程导弹类似。不过，美国方面的人员表示，北极星-2采用固体火箭发动机，而朝鲜4月试射的导弹采用液体燃料。     韩国未来可能会采购更多的射程为300～500千米的玄武-2系列战术近程弹道导弹及射程为500～1000千米的玄武-3系列巡航导弹。而射程达到800千米的新型弹道导弹将提高韩国应对朝鲜威胁的能力。','paste','cmnee_test_1529.txt',431,'2026-06-16 13:15:12'),(88,'[CMNEE #1564] 日前二十四架美、英战机分从美国杜鲁门号航空母舰和波斯湾地区陆上基地起飞，并使用远距离精确制导武器攻击伊拉克首都巴格达周遭目标，击中雷达站和指挥所等设施。这是美国...','日前二十四架美、英战机分从美国杜鲁门号航空母舰和波斯湾地区陆上基地起飞，并使用远距离精确制导武器攻击伊拉克首都巴格达周遭目标，击中雷达站和指挥所等设施。这是美国总统布什上任以来首次大规模动用美国军力；此次也凸显了航空母舰在二十一世纪战争中仍将扮演关键性的重要角色。美国是全球建造与使用航母最多的国家。其海军现有航母包括常规动力航母独立号、小鹰号、星座号以及预备及训练用之肯尼迪号等四艘；核动力航母则有企业号、尼米兹号、艾森豪威尔号、卡尔文森号、罗斯福号、林肯号、华盛顿号、斯坦尼斯号与杜鲁门号等九艘。这些航母分别部署在全球各战略要地，一旦战争爆发，可将强大兵力迅速投射现场，加入作战行列。而此次担纲出袭伊拉克要角的杜鲁门号，系美国海军最新一艘常规起降航母，于一九九八年下水服役，属尼米兹级核动力航母。','paste','cmnee_test_1564.txt',350,'2026-06-16 13:15:12'),(89,'[CMNEE #1601] 印度从俄制塔卡什号导弹护卫舰上成功试射了布拉莫斯巡航导弹。 塔卡什号以及另外两艘改进型克里瓦克Ⅲ级护卫舰泰格号和特里坎德号护卫舰都将装备布拉莫斯导弹。这三艘护卫...','印度从俄制塔卡什号导弹护卫舰上成功试射了布拉莫斯巡航导弹。 塔卡什号以及另外两艘改进型克里瓦克Ⅲ级护卫舰泰格号和特里坎德号护卫舰都将装备布拉莫斯导弹。这三艘护卫舰的前两艘泰格号和塔卡什号已经服役印度海军，第三艘特里坎德号也即将交付。 布拉莫斯导弹是基于俄罗斯3M55宝石中程反舰导弹研制的， 射程为290千米，能携带总重量达300千克的常规弹头，并能有效地摧毁高度低到10米的目标，其最高速度为2.8马赫数，是美国战斧亚声速巡航导弹的3倍。 印度目前还正在研制潜射型和装备苏-20MKI的机载型布拉莫斯导弹。','paste','cmnee_test_1601.txt',254,'2026-06-16 13:15:12'),(90,'[CMNEE #1626] 2015年5月23日，澳大利亚国有ASC造船厂霍巴特级驱逐舰首舰霍巴特号下水，排水量7000吨。该项目计划建造3艘舰艇，目前进度推迟、费用大幅上涨。 该项目最初...','2015年5月23日，澳大利亚国有ASC造船厂霍巴特级驱逐舰首舰霍巴特号下水，排水量7000吨。该项目计划建造3艘舰艇，目前进度推迟、费用大幅上涨。 该项目最初的预计造价为72亿澳元，目前已延迟了2年交付；而近期的政府评估报告称，相关费用已上涨9.32亿澳元，舰艇交付还将再推迟一年。根据政府报告，目前估计霍巴特级驱逐舰项目最终可能增加12亿澳元的额外成本。 霍巴特号预计2017年6月交付，第二艘布里斯班号和第三艘悉尼号则预计分别于2018年9月和2020年交付。 霍巴特级驱逐舰基于宙斯盾作战系统，装备SPY-1D搜空雷达，48单元Mark 41垂直发射系统，可发射标准-2导弹和RIM-162改进型海麻雀。 报告还提到，澳大利亚政府希望可引入另一个承包商协助完成霍巴特级驱逐舰项目。','paste','cmnee_test_1626.txt',344,'2026-06-16 13:15:12'),(91,'[CMNEE #1628] 通用动力公司研制的北达科他州号核动力攻击潜艇成功在水下发射并回收REMUS600型无人潜航器。 北达科他州号核动力攻击潜艇在地中海执行为期2个月的部署任务后返回...','通用动力公司研制的北达科他州号核动力攻击潜艇成功在水下发射并回收REMUS600型无人潜航器。 北达科他州号核动力攻击潜艇在地中海执行为期2个月的部署任务后返回美国本土。指挥官道格拉斯・戈登说，潜艇在发射回收REMUS600自主式无人潜航器的过程中，并不影响潜艇的其他作业。 REMUS600无人潜航器由挪威康斯伯格海事公司研制，美国海军研究署提供了资金支持，可执行水雷对抗、港口安全和搜救任务。 由于无线电信号无法在水下传播，而声学信号的传播速度比无线电慢很多，因此无人潜航器的水下通信以及操控十分困难，因此，无人潜航器不得不接近完全自主作业。 戈登还补充说美国海军正在测试和不同种类的无人潜航器，并在2016年的政府国防预算中获得了大量的资金支持，用于扩大无人潜航器编队的规模。','paste','cmnee_test_1628.txt',341,'2026-06-16 13:15:12'),(92,'[CMNEE #1656] &nbsp;&nbsp;&nbsp; 据比利时海军认知网站2019年12月15日报道，当地时间12月12日下午，日本海上自卫队最新一艘淡路级扫雷舰在横滨造船厂举...','&nbsp;&nbsp;&nbsp; 据比利时海军认知网站2019年12月15日报道，当地时间12月12日下午，日本海上自卫队最新一艘淡路级扫雷舰在横滨造船厂举行下水仪式，并被命名为江田岛号。该型舰由日本造船联合公司研制，被称为平成29年度计划扫雷舰，旨在增强日本海上自卫队的扫雷能力，确保海上基础设施的安全，共订购3艘，首舰于2015年10月下水，2017年3月交付；2号舰平户号2017年2月下水，2018年3月交付。该型舰标准排水量690吨，长67米，舷宽11米，高5.2米，吃水2.7米，配备两台2200马力柴油发动机，双轴，最高航速14节，装备有一门JM61-RFS式六管20毫米自动机炮，可提供高空防御能力。淡路级扫雷舰增强了对中/浅深度海域复杂环境水雷的处理能力，船尾装有可变深度声纳系统，以检测、定位和分类不同深度下水雷、潜艇等水下物体，并可携带水下检查设备和无人潜航器，用于检查、定位和清除水雷。','paste','cmnee_test_1656.txt',407,'2026-06-16 13:15:12'),(93,'[CMNEE #1700] 澳大利亚皇家海军本周早前宣布，澳大利亚首艘装备美国宙斯盾作战系统的驱逐舰霍巴特号已经完成了武器和系统评估。     霍巴特级驱逐舰总共计划建造3艘，总造价为65...','澳大利亚皇家海军本周早前宣布，澳大利亚首艘装备美国宙斯盾作战系统的驱逐舰霍巴特号已经完成了武器和系统评估。     霍巴特级驱逐舰总共计划建造3艘，总造价为65亿美元。首舰霍巴特号于2017年9月入役，第二艘舰布里斯班号于2018年10月下水，最后一艘悉尼号计划于2020年3月交付。     宙斯盾作战系统是美国海军舰载防空系统的核心。据俄罗斯卫星通讯社当时的报道，洛克希德・马丁公司系统公司于2017年7月获得了一份价值4100万美元的合同，为新舰提供计算机程序维护服务。     阿利伯克级舰约翰芬恩号去年11月在夏威夷海岸帮助霍巴特测试了其传感器网系统。     澳大利亚皇家海军已经开始了雄心勃勃的发展计划，订购了最先进的反潜战系统，并计划在未来二十年里每隔18到24个月就接收一艘新舰艇。     2017年5月发布的《澳大利亚海军造船计划》计划为舰艇建造提供653亿美元、为船厂改造和工作人员再培训提供10亿美元。该计划包括建造2艘直升机登陆船坞、10多艘新型潜艇和9艘护卫舰。      ','paste','cmnee_test_1700.txt',452,'2026-06-16 13:15:12'),(94,'[CMNEE #1751] 德国国防部官员说，9月7日，德国国防部将向国会提出RBS-15 MK3 导弹的购买计划。 《防务新闻》于8月24日获悉，德国国防部计划购买30枚RBS-15 M...','德国国防部官员说，9月7日，德国国防部将向国会提出RBS-15 MK3 导弹的购买计划。 《防务新闻》于8月24日获悉，德国国防部计划购买30枚RBS-15 MK3 导弹装备其海军的K-130型轻护舰。 合同商是Diehl BGT Defense 和瑞典萨伯公司，合同价值6803万欧元，分为3个采购节点。2007年，向德国交付首批的2枚导弹，2008年交付5枚，2009年交付23枚。2008年，最后1艘K-130型轻护舰将于2008年下水。 德国国防部于今年将拨款500万欧元用于该项计划，2006年、2007年和2008年各拨款1500万欧元，2009年拨款1900万欧元。 德国国防部官员说，对于德国海军而言，RBS-15 MK3 导弹是K-130轻护舰的主要武器，它是性能优良的反舰导弹，也能用于对付陆地目标。','paste','cmnee_test_1751.txt',360,'2026-06-16 13:15:12'),(95,'[CMNEE #1754] 洛克希德・马丁公司及其团队近日完成了近海战斗舰另外一个关键的里程碑，为自由号近海战斗舰安装了 2 台主推进燃气轮机。            自由号近海战斗舰按计...','洛克希德・马丁公司及其团队近日完成了近海战斗舰另外一个关键的里程碑，为自由号近海战斗舰安装了 2 台主推进燃气轮机。            自由号近海战斗舰按计划将在2006年夏季下水，并于2007年年初交付美国海军。      自由号近海战斗舰采用柴-燃联合动力装置以及喷水推进器。舰上安装的2台罗尔斯-罗伊斯公司的MT 30燃气轮机，是美国海军舰艇上安装的最大的燃气轮机，从而使得近海战斗舰在高速轻载时持续航速可超过40节。舰上安装的柴油机由Fairbanks Morse公司提供，为近海战斗舰提供远程巡航能力。2部固定和2部易操纵的罗-罗公司喷水推进器可使近海战斗舰在执行任务的时候具备超强的机动能力。       洛克希德・马丁公司团队的近海战斗舰设计采用了半滑行钢材料单体船型，可提供优越的机动能力和良好的适航能力，可支持布放和回收作业，为船员提供了最佳的舒适性。近海战斗舰将是美国海军第一级按照美国航运局新海军舰艇规范入级的海军舰艇。','paste','cmnee_test_1754.txt',423,'2026-06-16 13:15:12'),(96,'[CMNEE #1770] 美国海军正在考虑为濒海战斗舰研制一种指挥控制系统，使该型舰具备控制一支两栖特混舰队执行相关任务的能力。       LCS目前的专用使命模块可执行反水雷、反潜和...','美国海军正在考虑为濒海战斗舰研制一种指挥控制系统，使该型舰具备控制一支两栖特混舰队执行相关任务的能力。       LCS目前的专用使命模块可执行反水雷、反潜和反舰任务，但美海军正考虑一项新的提议，在建立美国非洲司令部的过程中，将这型舰艇作为近海指挥舰部署。       美海军曾计划在2012财年采购一艘JCC-X指挥舰来替换两艘贝劳・伍德级指挥舰和蓝岭级指挥舰惠特尼山号，JCC-X计划曾在2003年被取消，但在美海军2006年的海军舰艇年度长期建造计划中恢复。       新的提议要求在LCS上装备一种中等级的指挥模块。美海军认为，更大型的指挥模块可装备大甲板两栖舰，如一艘圣安东尼奥级两栖船坞运输舰，而不是建一艘新的舰艇。目前，洛克希德・马丁公司正美海军的合同下建造两艘LCS，其中第一艘自由号已在今年9月下水。而通用动力公司正在建造独立号，将在2007年初交付，该公司的第二艘LCS将在12月签订建造合同。','paste','cmnee_test_1770.txt',409,'2026-06-16 13:15:12'),(97,'[CMNEE #1784] 新西兰4艘海岸巡逻舰于12月11日在新西兰璜加雷港下水，该舰全部在新西兰建造，由璜加雷市的泰尼克斯船厂建造。 这是新西兰海军在保护者工程下采购7艘新舰过程中的又...','新西兰4艘海岸巡逻舰于12月11日在新西兰璜加雷港下水，该舰全部在新西兰建造，由璜加雷市的泰尼克斯船厂建造。 这是新西兰海军在保护者工程下采购7艘新舰过程中的又一个重要台阶。第1艘舰为 坎特伯雷号多功能舰，于今年6月在新西兰海军服役。第1艘近海巡逻舰OTAGO号于2006年11月在威廉斯镇下水，第2艘近海巡逻建惠灵顿号于今年10月在威廉斯镇下水。 上个月，哈威亚号的姊妹舰即首艘海岸巡逻舰罗托伊蒂号，在璜加雷港区域成功完成了海试。罗托伊蒂号于今年7月底下水，下水一周后在璜加雷的泰尼克斯船厂举行命名仪式。 至2008年年底，新西兰海军的保护者舰队将由3型7艘舰艇组成：1艘多功能舰、2艘近海巡逻舰和4艘海岸巡逻舰。 哈威亚号将于12月15日举行命名仪式。泰尼克斯船厂预计2008年中期完成哈威亚号的舾装并正式交付海军。','paste','cmnee_test_1784.txt',360,'2026-06-16 13:15:12'),(98,'[CMNEE #1956] 加拿大国防部长希望4艘受到困扰的加拿大潜艇可以在2014年正常工作。 其中的1艘潜艇温莎号在今天下水进入哈利法克斯港，这是该潜艇过去五年内首次进入水中。 温莎号...','加拿大国防部长希望4艘受到困扰的加拿大潜艇可以在2014年正常工作。 其中的1艘潜艇温莎号在今天下水进入哈利法克斯港，这是该潜艇过去五年内首次进入水中。 温莎号潜艇是整修计划后今年第二艘开始海试的潜艇。 其整修工作在2009年完成，但是已经花费了差不多五年的时间。该潜艇自从2001年10月到达新斯科舍，仅在海上停留了332天。 维多利亚号潜艇的基地在西海岸，其是首艘完成整修的潜艇，并在上个月成功试验了鱼雷发射。 除了计划的整修外，潜艇经常发生事故进一步推迟了潜艇的运行使用。 希库蒂米号潜艇在2004年向加拿大航行期间，潜艇发生火灾，导致海水损坏了电子系统，并有一名艇员死亡。 维多利亚号潜艇最近完成了3年的整修，包括修理妨碍潜艇深潜的艇体凹陷。','paste','cmnee_test_1956.txt',325,'2026-06-16 13:15:12'),(99,'[CMNEE #2087] 美国海军巡洋舰钱瑟勒斯维尔号11月17日周六下午，在南加州外海穆古岬海军基地外进行一项无人机测试时发生事故，无人机转向失控，撞上军舰，造成两名士兵轻微灼伤和舰体...','美国海军巡洋舰钱瑟勒斯维尔号11月17日周六下午，在南加州外海穆古岬海军基地外进行一项无人机测试时发生事故，无人机转向失控，撞上军舰，造成两名士兵轻微灼伤和舰体部分损伤。 美军第三舰队发言人在一份声明中表示，事故发生在当地时间下午1点25分，军方利用远程操控的无人机在海军钱瑟勒斯维尔号巡洋舰上进行例行雷达系统测试时，无人机怀疑机件失灵，突然急坠，撞上军舰，造成舰体部分损伤，需要即时返回位于圣迭哥的海军基地进行评估和检修。美军称，受损的巡洋舰上当时官兵近300人，目前美国海军正在就无人机故障事故原因展开调查。 美国宙斯盾导弹巡洋舰钱瑟勒斯维尔号属于美海军提康德罗加级巡洋舰。该舰长172.5米，宽16.8米，标准排水量为726O吨，满载排水量为9460吨。最大航速30节，巡航速度20节，续航力6000海里，自给能力12天，人员编制为358人。','paste','cmnee_test_2087.txt',374,'2026-06-16 13:15:12'),(100,'[CMNEE #2334] 美联社6月21日基辅电，欧盟已帮助乌克兰安装了一个有助于该国防止和应对将来潜在紧急事件的核应急响应系统。乌克兰在欧洲委员会的首席代表Norbert Jouste...','美联社6月21日基辅电，欧盟已帮助乌克兰安装了一个有助于该国防止和应对将来潜在紧急事件的核应急响应系统。乌克兰在欧洲委员会的首席代表Norbert Jousten和乌克兰环境部长Serhiy Kurykin说，该系统在欧洲最大的核电站--扎波罗热核电站进行多次测试后，不久将投入使用。乌克兰官员称，RODOS系统的监测范围不包括乌克兰的其它三个核电站。Jousten说，欧洲已有几个国家安装了这种RODOS应急响应系统，并在斯洛伐克、波兰、匈牙利进行了测试。并称，欧盟计划帮助俄罗斯和白俄罗斯安装类似的应急响应系统。此前，乌克兰已安装了放射监测系统。1986年，乌克兰发生了世界上最为严重的核事故，切尔诺贝利核电站的4号机组发生爆炸，喷出的放射云弥漫区域达欧洲的大部分地区。该电站于2000年成功关闭，但解组工作仍在继续。','paste','cmnee_test_2334.txt',361,'2026-06-16 13:15:12'),(101,'[CMNEE #2335] 朱姆沃尔特号驱逐舰此前在返航母港时出现多次故障，美海军目前已经为这一问题找到并测试了解决方案。         此前，朱姆沃尔特号驱逐舰返航母港时，舰上润滑油冷...','朱姆沃尔特号驱逐舰此前在返航母港时出现多次故障，美海军目前已经为这一问题找到并测试了解决方案。         此前，朱姆沃尔特号驱逐舰返航母港时，舰上润滑油冷却器故障，导致海水多次渗入推进系统，其中一次导致在通过巴拿马运河时动力系统停止工作。         朱姆沃尔特号驱逐舰项目负责人称，海水润滑油冷却器可防止转轴由于热或摩擦作用出现断裂。类似其他平台系统，当海水和钢铁混合后，总会出现问题。此前，通用动力巴斯钢铁船厂在码头对舰艇电力推进系统进行了全面地测试，但润滑油冷却器的问题却只在舰艇在航时才发现。海军认为，由于冷却要求不高，可采取用淡水冷却的方法。         自去年12月，舰艇抵达圣地亚哥后，美海军已经对淡水冷却器开展了两次在航测试。这项修正可有效解决问题，并已经用于在建的DDG-1001和DDG-1002号舰。         海上系统司令部也在评估这项问题的最终解决方案，设计新的冷却器，用于该级前三艘外的更多舰艇。此外，美海军还在考虑创建一项新的冷却器军标，要求具有30年以上的寿命。','paste','cmnee_test_2335.txt',457,'2026-06-16 13:15:12'),(102,'[CMNEE #2663] 德国IdZ未来士兵系统在返回德国之前，先在位于瑞典Borensberg Kvarn的陆军作战学院进行展示。MARKUS研究室已经于2006年秋对德国未来士兵系统...','德国IdZ未来士兵系统在返回德国之前，先在位于瑞典Borensberg Kvarn的陆军作战学院进行展示。MARKUS研究室已经于2006年秋对德国未来士兵系统进行了为期8周的测试。试验首先在德国Hammelburg的军方试验场展开，内容是向MARKUS研究室的军官介绍德国未来士兵系统。然后全套装备被运送至瑞典，由两栖作战兵团配装未来士兵系统在瑞典首都斯德哥尔摩的贝尔格Amf 1进行一系列试验。 对德国未来士兵系统进行试验的目的是为了测试单兵使用全套士兵系统时能力大小如何，同时也是为了测试团队变化时使用全套士兵系统所具有的能力。试验结果将与MARKUS研究室之前于2002年～2006年开展的试验进行比较。关于德国未来士兵系统的最后报告将于2007年早些时候完成，并将递交给德国。 ','paste','cmnee_test_2663.txt',344,'2026-06-16 13:15:12'),(103,'[CMNEE #2779] 9月27日，伊朗伊斯兰革命卫队开始举行代号为神圣先知4的军事演习。演习当日，伊朗试射三枚短程导弹。 革命卫队发布的声明称，此次代号伟大先知的演习为期5天，以试射...','9月27日，伊朗伊斯兰革命卫队开始举行代号为神圣先知4的军事演习。演习当日，伊朗试射三枚短程导弹。 革命卫队发布的声明称，此次代号伟大先知的演习为期5天，以试射各种型号的国产导弹为主，主要目的是巩固和维持伊朗武装力量的威慑力。27日试射的导弹为汤达69型、征服者110型和地震类型的导弹。三枚导弹均使用固体燃料，射程在100-400千米之间。 9月27日，护卫队还试验了首个多用途导弹发射装置。伊朗半官方媒体法尔斯通讯社称多用途发射装置可以同时发射两枚目标不同的导弹。该系统发射数枚导弹均成功击中虚拟目标。发射的导弹包括伊朗自制的地对地和舰对舰短程导弹。 伊朗空军司令萨拉米称28日还将发射一枚流星-3导弹，该导弹射程覆盖以色列。伊朗还将试射流星-1和流星-2中程导弹。伊朗已经提高了导弹精确性，但在持续数日的演习中，护卫队不会发射新型导弹。 伊朗此次演习在美国总统奥巴马宣布调整欧洲导弹防御计划之后。此外，9月25日，国际原子能机构宣布伊朗正在建设第二座核电站，引起西方领导人的关注。 ','paste','cmnee_test_2779.txt',444,'2026-06-16 13:15:12'),(104,'[CMNEE #2958] 印度将于近期接收租期10年的俄罗斯弹道-鱼雷核潜艇海豹号。该艇的测试将在8月底完成。 印度海军将海豹号重新命名为查克拉号。租赁海豹号是一份价值6.5-7亿美元的...','印度将于近期接收租期10年的俄罗斯弹道-鱼雷核潜艇海豹号。该艇的测试将在8月底完成。 印度海军将海豹号重新命名为查克拉号。租赁海豹号是一份价值6.5-7亿美元的秘密协议。目前，印度船员与俄罗斯专家开始在日本海训练各种任务。 查克拉号将于11月抵达印度东海岸拉姆毕尔的弹道导弹核潜艇专用基地，2011年底在印度海军服役。查克拉号服役后，印度将成为世界上继中国、法国、俄罗斯、英国、美国后第6个拥有核潜艇的国家。 印度海军方面拒绝对海豹号潜艇计划进行评论，但是从莫斯科的报道可以证实该项目的进展情况。 查克拉号将成为印度海军的训练平台，为印度第一艘国产设计建造核潜艇歼敌者号培训人员。歼敌者号须在2012年底携带全套的远程导弹武器下水。印度海军计划建造3-5艘国产弹道导弹核潜艇。','paste','cmnee_test_2958.txt',338,'2026-06-16 13:15:12'),(105,'[CMNEE #215] 【环球网报道 见习记者 马岩】据《防务新闻》网站7月14日报道，发生火灾的两栖攻击舰好人理查德号之前已接近完成两年升级任务并具备搭载F-35B第五代战斗机的能力...','【环球网报道 见习记者 马岩】据《防务新闻》网站7月14日报道，发生火灾的两栖攻击舰好人理查德号之前已接近完成两年升级任务并具备搭载F-35B第五代战斗机的能力，它的退出意味着美国在太平洋部署五代机的能力受到影响。2018年，海军给予通用动力公司和国家钢铁与造船公司2.19亿美元现代化升级合同，共升级改造4艘大型两栖攻击舰，其中包括好人理查德号。燃烧中的好人理查德号有专家表示，无论美海军完全失去好人理查德号，还是需要对其大规模维修，都对美海军持续在太平洋部署F-35B的计划是一个沉重打击。美国海军打算在印太、中东等重点地区不间断地部署F-35B，为达到这一目标，美海军需要在任何时间保持一艘两栖攻击舰前沿部署、一艘在紧急情况下可随时出动、一艘在维护修理中，以及一艘在进行部署前的检查。换句话说，美海军至少需要4艘两栖攻击舰，才能保证一艘处于部署状态，如果算上F-35B战斗机的升级时间，则需要5艘舰。目前，海军只能选择让其它两栖攻击舰部署更长时间，或重新启用已经封存的塔拉瓦级攻击舰来填补空缺。','paste','cmnee_test_215.txt',450,'2026-06-16 13:15:12'),(106,'[CMNEE #264] 资料图：美国海军CVN-73华盛顿号航母 　　中新网8月22日电 5月发生火灾的美国海军乔治-华盛顿号核动力航母于当地时间21日上午修理完毕，驶离加利福尼亚州圣...','资料图：美国海军CVN-73华盛顿号航母 　　中新网8月22日电 5月发生火灾的美国海军乔治-华盛顿号核动力航母于当地时间21日上午修理完毕，驶离加利福尼亚州圣迭戈海军基地，前往部署地日本神奈川县的美国海军横须贺基地。预计抵达时间为9月下旬。华盛顿号将接替常规动力航母小鹰号，成为第一艘驻扎在美国本土以外的核动力航母。　　据日本共同网报道，华盛顿号5月在太平洋南美洲海域因船员吸烟引发火灾，造成37人受伤，舰长也被撤换。火灾后华盛顿号在圣迭戈基地进行了修理。此外，舰上两名士兵日前刚在加利福尼亚州因涉嫌杀人被逮捕。加之停泊在美国海军佐世保基地的核潜艇也被曝发生核物质泄漏，美军的安全管理漏洞和松散军纪加剧了日方的不安。为挽回形象，华盛顿号舰长亨利在本月7日的记者会上保证说能够安全航行，希望得到日方的谅解。　　华盛顿号于1992年服役。排水量约为10万吨，装有2座可同小型核电站媲美的加压水反应堆，最高航速超过30节。','paste','cmnee_test_264.txt',409,'2026-06-16 13:15:12'),(107,'[CMNEE #480] 据以色列电台报道，以色列国防军在５日进行的首次箭式导弹防御系统多导弹截击军事演习中，成功地使用四枚同时发射的箭式拦截导弹将假想目标击中。 报道说，此次军事演习是...','据以色列电台报道，以色列国防军在５日进行的首次箭式导弹防御系统多导弹截击军事演习中，成功地使用四枚同时发射的箭式拦截导弹将假想目标击中。 报道说，此次军事演习是在以中部地区空军基地进行的。以空军、海军作战部队指挥官和美国军方高层人士观摩了此次演习。 以色列空军指挥官哈鲁茨将军在演习开始前表示，如果演习取得成功，就说明以色列有能力从容应对可能遭受的地对地导弹的袭击。他说，目前伊拉克空军实力和导弹发射能力已十分有限，而且以军已对伊拉克在遭受美军事打击后对以采取报复袭击的各种可能性做好了充分准备。 报道透露，本周晚些时候，以色列还将与美国联合举行导弹拦截演习。届时，美军将启动爱国者导弹防御系统，协同以色列的箭式系统对假想目标实施空中拦截。 由美国出资、以色列负责研制的箭式导弹防御系统被认为是世界第一套用于截击中、短程弹道导弹的防御系统。目前，以国防军已在北部沿海城市哈代拉和南部迪莫纳核电站附近部署了两套箭式系统，并计划在近期内部署第三套箭式系统。','paste','cmnee_test_480.txt',426,'2026-06-16 13:15:12'),(108,'[CMNEE #511] 周日，军事权威说韩国将在南部的济州岛附近主办一次五国潜艇救援训练。 韩国国防部长说，该训练将从5月3日开始，5月13日结束，共有来自韩国、美国、日本、澳大利亚和...','周日，军事权威说韩国将在南部的济州岛附近主办一次五国潜艇救援训练。 韩国国防部长说，该训练将从5月3日开始，5月13日结束，共有来自韩国、美国、日本、澳大利亚和新加坡的4艘潜艇、4艘救援船和3艘深潜救生器参加。美国的潜艇是6900吨级的，韩国的是1200吨级的。两年一次的救援训练是从2000年开始举办的，主要是为了提高营救失事潜艇的能力。前两次分别是由新加坡和日本主办的。 南北朝鲜自战后技术上一直相互保密，北朝鲜目前有90多艘潜艇；韩国目前有9艘1200吨的潜艇，计划从2007年开始部署3艘1800吨的潜艇，这些潜艇安装的都是德国设计的柴油机或柴电发动机。 根据与美国签订的一份军事协议，美国核动力潜艇将对朝鲜半岛进行巡逻。 ','paste','cmnee_test_511.txt',316,'2026-06-16 13:15:12'),(109,'[CMNEE #569] 6月17日，黎巴嫩海军接收了德国海军二手巡逻艇卑尔根号，并举行了移交仪式。 这艘艇长28米，以前被德国海军用作巡逻艇，最初是在波罗的海负责训练区域安全。这艘艇是...','6月17日，黎巴嫩海军接收了德国海军二手巡逻艇卑尔根号，并举行了移交仪式。 这艘艇长28米，以前被德国海军用作巡逻艇，最初是在波罗的海负责训练区域安全。这艘艇是采用船坞舰从汉堡运送到仪式现场的。 这次交付只是德国海军对这一区域安全所作出贡献中的一部分，除此以外还有德国导弹护卫舰黑森号作为旗舰也部署在此区域。德国舰艇和海军安全部队为了支持UNIFIL，已经在此区域进行了部署。 卑尔根号是德国向黎巴嫩移交的第三艘舰艇，前两艘都是德海军的前海事警务巡逻艇，分别为不莱梅 2号和不莱梅 9号，这两艘艇目前正在贝鲁特执行任务，分别命名为阿姆希特和纳科拉号。根据黎巴嫩政府的数据，目前黎巴嫩海军的舰艇组成为：2艘法国建造的LCVP，7艘英国建造的刚性气胀艇以及27艘英国建造的战斗支援船。 出席移交仪式的有新任命的黎巴嫩海军司令官；德国舰队司令官以及德国外交部的一些代表。这艘艇在黎巴嫩被重新命名为塔巴加号。','paste','cmnee_test_569.txt',400,'2026-06-16 13:15:12'),(110,'[CMNEE #576] 美国空军最近在新墨西哥州的白沙导弹靶场，由B-1B轰炸机和F-16战斗机分别于1月25日和1月27日，再次成功地进行了联合防区外空地导弹的飞行试验。该导弹飞行试...','美国空军最近在新墨西哥州的白沙导弹靶场，由B-1B轰炸机和F-16战斗机分别于1月25日和1月27日，再次成功地进行了联合防区外空地导弹的飞行试验。该导弹飞行试验项目是美国空战司令部优先实施的项目之一，从2005年1月开始进行飞行试验以来，迄今为止，共进行43次，其中33次飞行成功；发射导弹数目13枚，11枚命中目标。   该导弹已装备B-1B和B-52轰炸机，预计在今年3月中旬开始装备F-16战斗机和B-2轰炸机，将用来攻击敌方高价值的固定目标和重新定位的目标，其特点之一是具有远距防区外攻击能力，其射程为空军现有武库中的其他空地攻击武器的4～5倍多，从而使该导弹载机及其空勤人员远处于敌方防空武器火力杀伤范围之外。美国空军现在已经部署有330多枚该导弹,，到2020年将增加到4700多枚。此外，美国空军的联合防区外空地导弹-增程开始进入试验阶段，其射程为JASSM导弹的2.5倍多。','paste','cmnee_test_576.txt',396,'2026-06-16 13:15:12'),(111,'[CMNEE #610] 作为2006~2007年度训练内容的一部分，朝鲜空中与防空司令部于2006年10月19日～25日至少发射了5枚地空导弹和空空导弹。据报道，此次试验是在西部地区的...','作为2006~2007年度训练内容的一部分，朝鲜空中与防空司令部于2006年10月19日～25日至少发射了5枚地空导弹和空空导弹。据报道，此次试验是在西部地区的训练场进行的。从以往的经验看，朝鲜进行这样的试验不是在位于首都平壤西面的区域进行，就是在再向北部、身弥岛周围进行。后者位于朝鲜主要航空研发中心的西南方。作为2005～2006年度训练内容的一部分，朝鲜也曾于2006年3月进行过一次相似的实弹射击演习。在那次试验中，他们发射了SA-2/HQ-2B和AS-3地空导弹，但不清楚是否发射了SA-5或SA-6地空导弹。目前，朝鲜正在研制SA-2地空导弹的一种变型产品，并将部署一种基于59式主战坦克底盘的SA-2自行发射器。直到目前为止，所发射的空空导弹尚未披露，但有可能是AA-8蚜虫空空导弹或一种由国内改进的其他空空导弹。','paste','cmnee_test_610.txt',364,'2026-06-16 13:15:12'),(112,'[CMNEE #720] 少数英国皇家海军灰背隼Mk1直升机装备了根据紧急作战需求采购的新型防御装置，以帮助直升机在前线作战。 洛克希德•马丁公司的官员在表示2月16日表示，该防御装置使...','少数英国皇家海军灰背隼Mk1直升机装备了根据紧急作战需求采购的新型防御装置，以帮助直升机在前线作战。 洛克希德•马丁公司的官员在表示2月16日表示，该防御装置使灰背隼直升机的作战性能产生阶跃性提升，使其能够担当新的任务，在新的威胁环境中作战。 灰背隼Mk1直升机主要用于反潜，但是在放弃任务系统之后，它也能被快速部署用于事故疏散、部队保护、搜索、营救和其它任务。 洛克希德•马丁公司、BAE系统公司、奎奈蒂克公司和其它公司根据2008年1月英国国防部授予的一项价值1010万美元的合同，联合在直升机上集成、测试和安装新型传动装置。 洛克希德•马丁公司的发言人拒绝透露涉及升级项目的直升机数量。 此次升级是在独立的紧急作战需求下，英国国防部更广泛的灰背隼直升机性能提高工作的一部分。 一些灰背隼直升机将安装能够将图像发送到地面的全动态摄像机以及一具威斯卡姆公司的MX15光学吊舱。 一位英国皇家海军的官员在最近举行的庆祝首艘45型驱逐舰抵达母港朴茨茅斯港的欢迎仪式上透露，传感器系统的测试将很快进行。','paste','cmnee_test_720.txt',449,'2026-06-16 13:15:12'),(113,'[CMNEE #841] 6月8日，伊朗海军副司令少将穆萨维表示，伊朗近期将对国产潜艇原型艇进行测试。在军事演习中完成对其进行的一系列测试之后，伊朗国产新型潜艇将加入海军作战舰队。 副司...','6月8日，伊朗海军副司令少将穆萨维表示，伊朗近期将对国产潜艇原型艇进行测试。在军事演习中完成对其进行的一系列测试之后，伊朗国产新型潜艇将加入海军作战舰队。 副司令穆萨维并没有进一步透露关于新型原型艇的技术规格、排水量以及何时进行演习等更多详情。 伊朗经常夸大其技术成果，自夸可能够更好地探测本地区其他国家和西方国家对其发动的攻击。 本周二，据报道，伊朗潜艇已被派遣到红海，进行情报收集活动，并对外国潜艇、水面舰艇的活动进行监视。 去年8月，伊朗宣称其将扩大潜艇舰队，伊朗目前已经拥有11艘潜艇，这些潜艇主要承担在波斯湾和阿曼海海域的巡逻任务。之前，伊朗已经派遣水面舰队到达诸如红海和地中海之类的远海地区执行任务，但却是第一次派遣潜艇到这些地区。','paste','cmnee_test_841.txt',322,'2026-06-16 13:15:12'),(114,'[CMNEE #893] 雷神公司的移动自适应互操作网络网关无线电系统成功在美国陆军两大演习中演示了战术网络能力，为士兵提供可靠的战场信息。 在最近佐治亚州本宁堡举行的远征军战士实验中，...','雷神公司的移动自适应互操作网络网关无线电系统成功在美国陆军两大演习中演示了战术网络能力，为士兵提供可靠的战场信息。 在最近佐治亚州本宁堡举行的远征军战士实验中，MAINGATE为骨干网提供宽带网络能力。它还替代已取消的地面移动无线电项目，成功完成了得克萨斯州布利斯堡举行的网络集成评估。在测试过程中，MAINGATE同时提供多通道的实时视频、态势感知、聊天和其他应用程序。班级士兵能够可靠接收多个无人机视频信息和其他高带宽数据服务，保持战术优势。MAINGATE提供蜂窝网络、手持无线电和WIN-T网之间所需的可靠连接能力。它也允许士兵融合整个作战指挥系统和传感器的信息。MAINGATE包含一个采用下一代移动自适应网络波形的高吞吐量无线电和一个无缝战场连接网关。MAINGATE是一个目前正在生产的成熟现成系统，已在战区部署了100多套。在NIE测试中，MAINGATE非专有波形比其他竞标无线电提供10倍以上的网络容量，并支持4倍以上的节点链接。而且，它也超出了即将部署的中间层网络车载电台的宽带网络需求。','paste','cmnee_test_893.txt',455,'2026-06-16 13:15:12'),(115,'[CMNEE #898] 俄罗斯武装部队总司令尼古拉・马卡洛夫表示，西北风级两栖登陆舰的采购和建造有利于俄罗斯开发新的技术。 总司令表示：俄罗斯和法国成功执行了西北风级两栖舰的协议，法国...','俄罗斯武装部队总司令尼古拉・马卡洛夫表示，西北风级两栖登陆舰的采购和建造有利于俄罗斯开发新的技术。 总司令表示：俄罗斯和法国成功执行了西北风级两栖舰的协议，法国为俄罗斯建造2艘登陆舰，其中25%的设备将在俄罗斯建造。我们不只是重视舰艇本身，更重视俄罗斯工业需开发的技术。 今年2月1日在法国举行了第1艘西北风级两栖舰的钢板切割仪式，第1艘舰艇将于2014年交付海军，第2艘将在2015年底交付海军。 在采购的法国登陆舰上将部署俄制卡-52直升机，去年11月北方舰队完成了该型直升机海军型的试验。 根据两国签署的协议，法国将向俄罗斯转让登陆舰的建造工艺，以及西尼特-9作战信息指控系统，该系统也将用在在俄罗斯境内独立建造的后两艘西北风级两栖舰上。     西北风级两栖舰排水量21000吨，舰长210米，可布置16架重型直升机，可运输900名人员和70两装甲车。舰上大部分系统实现自动化，人员编制共有170人。 ','paste','cmnee_test_898.txt',405,'2026-06-16 13:15:12'),(116,'[CMNEE #1032] 法国陆军表示，2009年5月10日首批VBCI装甲车便已经开始装船，即将部署到驻阿富汗法军第35步兵团。据报道，2010年夏季期间，法国国防部将共完成2个排的V...','法国陆军表示，2009年5月10日首批VBCI装甲车便已经开始装船，即将部署到驻阿富汗法军第35步兵团。据报道，2010年夏季期间，法国国防部将共完成2个排的VBCI装甲车配置部署，届时还将与驻阿富汗法国第21海军陆战队步兵团和第126步兵团展开联合战术战斗操作。 目前，法国陆军已经向法国奈克斯特系统公司和雷诺卡车防务公司共采购了630辆VBCI装甲车，2008年完成首批车辆交付工作，预计全部交付工作将持续到2015年。法国奈克斯特系统公司是VBCI装甲车的主承包商，雷诺卡车防务公司属于子承包商，主要负责提供车辆的动力组件和行动装置。交付法国陆军的VBCI装甲车将用于替代现役履带式AMX-10P步兵战车和部分VAB 4×4车。该车共包含两种车型，分别为VPC指挥车和VCI步兵战车。其中，VCI步兵战车战斗全重30吨，可搭载乘员3人，载员8人，装备单人炮塔，其上配有M811式25毫米自动炮和7.62毫米并列机枪。该车最大行驶速度可达100千米/小时，可通过A400M运输机实施空运。 ','paste','cmnee_test_1032.txt',447,'2026-06-16 13:15:12'),(117,'[CMNEE #1620] 俄罗斯米格飞机制造公司圆满完成2014年国家国防订单，俄国防部委托米格飞机制造公司为俄海军制造先进的多功能舰载机米格-29K/ KUB，并于2012年2月签署了...','俄罗斯米格飞机制造公司圆满完成2014年国家国防订单，俄国防部委托米格飞机制造公司为俄海军制造先进的多功能舰载机米格-29K/ KUB，并于2012年2月签署了米格-29K/ KUB型战斗机的合同。首批飞机已于2013年交付俄罗斯国防部。 米格公司总经理谢尔盖・科罗特科夫表示，米格-29K/ KUB型的成功开发和批量生产开创了第4++代系列战斗机，在未来几年它将交付给俄罗斯国防部并用于出口。 米格-29K和米格29KUB作为第4++代多功能舰载机，它的主要任务是解决海上防空问题，其能在空中占据主导地位，完成全气候全天候海陆目标的精确打击。该机配备高比率复合材料的滑翔设备，数字集成的飞机控制系统，开放式结构的航空电子设备。显著降低了雷达信号，增加了燃料储备和作战载荷。 米格29KUB的原型机首飞于2007年1月。2009年米格公司开始向印度海军提供米格-29K/ KUB型战机。2009年米格-29K/ KUB在俄库兹涅佐夫号航母从重型飞行甲板上成功完成一系列飞行试验。','paste','cmnee_test_1620.txt',439,'2026-06-16 13:15:12'),(118,'[CMNEE #1753] 2008年7月底，美国陆军官员在德克萨斯州布利斯堡观看了在有限初期用户测试中的未来战斗系统性能演示之后，确信该系统能够挽救士兵生命，所以继续推动未来战斗系统加速...','2008年7月底，美国陆军官员在德克萨斯州布利斯堡观看了在有限初期用户测试中的未来战斗系统性能演示之后，确信该系统能够挽救士兵生命，所以继续推动未来战斗系统加速生产。       陆军官员在2008年7月27～31日在训练演习中测试了未来战斗系统螺旋发展1组件。该组件是由用于精确火力支援的非瞄准线发射系统、可共享图像的B组件计算机系统、I级0阶段无人机和小型无人地面车辆组成。       根据测试结果，陆军官员支持2009年开始下一阶段的测试即初期用户测试，到达里程碑C，2010年开始未来战斗系统螺旋发展1组件的限量生产。陆军第一个旅级战斗队将在2011年接收一套完整的未来战斗系统螺旋发展1组件。目前，陆军已经开始向部属在伊拉克和阿富汗的美国军队交付未来战斗系统螺旋发展1组件的零件，陆军和海军都将装备未来战斗系统无人机。','paste','cmnee_test_1753.txt',365,'2026-06-16 13:15:12'),(119,'[CMNEE #1858] 俄罗斯阿尔玛兹 船厂为越南海军建造的第二艘10412型轻护舰于4月22日下水。 该护卫舰2009年6月在阿尔玛兹船厂与该级另一艘舰同时铺设龙骨。这两艘轻护舰由越...','俄罗斯阿尔玛兹 船厂为越南海军建造的第二艘10412型轻护舰于4月22日下水。 该护卫舰2009年6月在阿尔玛兹船厂与该级另一艘舰同时铺设龙骨。这两艘轻护舰由越南海军订购，阿尔玛兹船厂曾于2002年向越南海军交付过两艘该级轻护舰。 10412型基于10410型Svetlyak级巡逻艇，由阿尔玛兹设计局在80年代研制，Svetlyak级巡逻艇旨在代替205P型毒蜘蛛级巡逻艇。 自项目启动开始，已为本国及外国客户建成34艘Svetlyak级舰艇，另外4艘该级舰艇​​正在建造中。与基本型不同的是，越南版本的该级舰艇上没有装备反潜武器，因此该级舰可作为巡逻艇或炮艇执行任务。基于第一批两艘舰艇的操作经验，越南海军决定订购另外4艘Svetlyak级舰艇，从阿尔玛兹船厂订购2艘，从Vostochnaya Verf船厂订购2艘。第1艘舰已于2010年11月下水。根据计划应在本年度建成全部4艘Svetlyak级舰并交付越南海军。 ','paste','cmnee_test_1858.txt',412,'2026-06-16 13:15:12'),(120,'[CMNEE #2097] 据法新社3月5日报道，印度星期二宣布，印度成功地试射一枚面空导弹。印度国防部官员在新德里说，印度时间下午5点25分，多目标导弹――Akash从奥里萨邦东部的导弹...','据法新社3月5日报道，印度星期二宣布，印度成功地试射一枚面空导弹。印度国防部官员在新德里说，印度时间下午5点25分，多目标导弹――Akash从奥里萨邦东部的导弹发射场点火发射。 据一位印度官员透漏，Akash射程25公里，早期经过几次试验，但是星期二发射的目的是对其导航系统进行测试。Akash重650公斤，装有一个能够跟踪其射程外64架飞机的雷达。6月上旬，印度试验了一枚海军地对空导弹――Trishul ，6月下旬发射了一枚具备核能力的近程弹道导弹――Agni I 。印度不断地发射导弹引起了国际社会对印度与巴基斯坦之间的新武器竞赛的广泛关注。继巴基斯坦袭击印度国会之后，印巴双边关系进入低潮，印度对两个巴基斯坦伊斯兰教军事组织予以谴责。印度和巴基斯坦在边境地区纠集了80万的军队，人们担心印巴之间会再次放生冲突。自从1947年以来，印度与巴基斯坦之间已经发生了3次战争。','paste','cmnee_test_2097.txt',388,'2026-06-16 13:15:12'),(121,'[CMNEE #2210] 资料图：印度租借俄罗斯的阿库拉级猎豹号核潜艇 　　新华网消息，据中国国防科技信息网报道印度海军期望已久的核潜艇——俄制阿库拉级潜艇有可能将在明年加入印度海军，印...','资料图：印度租借俄罗斯的阿库拉级猎豹号核潜艇 　　新华网消息，据中国国防科技信息网报道印度海军期望已久的核潜艇——俄制阿库拉级潜艇有可能将在明年加入印度海军，印度海军正全力准备通过潜艇发射核导弹以增强其国家的核威慑能力。　　印度海军已于今年二月第一次成功试射了一枚潜射弹道导弹，并准备再花费3年的时间将其应用于军事行动。　　在推迟交付日期后，这艘阿库拉级核潜艇很可能于明年加入印度海军服役，印度海军司令苏里什·梅塔指出，尽管阿库拉级潜艇可以用于军事行动，但在本国制造的核动力潜艇进行秘密建造)服役之前，印度将主要利用俄罗斯制造的潜艇来对人员进行训练。　　印度海军核动力潜艇项目是印度国防研究与开发组织的一项计划，该项目被称为先进技术舰船项目。据称，印度本国制造的核潜艇将于两年后进行试航。','paste','cmnee_test_2210.txt',344,'2026-06-16 13:15:12'),(122,'[CMNEE #2480] 一架V-22倾转旋翼机将于1月14日早在美国两栖舰Iwo Jima号上开始舰载飞行试验，由于上周发现了该机存在非关键的漏油，试验推迟了一天进行。 海军发言人Wa...','一架V-22倾转旋翼机将于1月14日早在美国两栖舰Iwo Jima号上开始舰载飞行试验，由于上周发现了该机存在非关键的漏油，试验推迟了一天进行。 海军发言人Ward Carroll 说，10号飞机将从拂晓起进行甲板上降落合格试验。他还说，维护人员已解决漏油问题，另外第21架飞机本周将开展空投试验。 本周的舰载试验是今年要进行的系列试验的首项内容，这些试验旨在消除对V-22项目产生的疑虑。在过去的试验中，分析家发现当飞机在旋翼旋转进行甲板上着陆时，飞机有翻转的危险。 海军希望飞行控制律的修改已解决了该问题。试验还将验证V-22的一个机翼在甲板上而另一个机翼在水面上时的起飞和着陆的能力。计划春天晚些时候的试验将测试飞机对涡环状态的敏感性，2000年该气动现象造成事故死亡了19名海军官兵。 五角大楼官员已指明，该项目的未来取决于今春飞行试验中飞机的表现。V-22曾经被考虑予以取消，但五角大楼现在希望，试验一旦成功将加速飞机生产进程。','paste','cmnee_test_2480.txt',419,'2026-06-16 13:15:12'),(123,'[CMNEE #2768] 曾在2008年11月的工厂航行试验时牺牲20人的海豹号核潜艇，将于今年7月初恢复试航，这一消息来源于太平洋舰队司令部。    海豹号核潜艇的试航计划在负责该舰恢...','曾在2008年11月的工厂航行试验时牺牲20人的海豹号核潜艇，将于今年7月初恢复试航，这一消息来源于太平洋舰队司令部。    海豹号核潜艇的试航计划在负责该舰恢复试验的国家委员会和专家们的工作完成之后，于7月上旬开始，目前正在进行的主要是试验前准备工作。 海豹号核潜艇是在阿穆尔造船厂建造的，2008年11月8日在日本海进行工厂航行试验时发现事故，原因是有人擅自启动灭火设备，导致氟利昂大量释放，造成20人牺牲，21人受伤。当时艇上共有208名官兵。 事故后工厂为潜艇的修复工作投入了5700万美元。 海豹号核潜艇属于俄罗斯第三代潜艇，在1991年开始建造。排水量为8140吨/12770吨，最大航速30节，最大潜深600米，自持力100天，舰员73名，武器包括：4枚533毫米鱼雷，4枚650毫米鱼雷。','paste','cmnee_test_2768.txt',352,'2026-06-16 13:15:12'),(124,'[CMNEE #12] 台军剑翔反辐射无人机平台/图：台湾中时电子报   据台湾中时电子报报道，继日前台军被曝出或将量产1500公里中程导弹后，台中科院航空所长齐立平14日声称，台军已...','台军剑翔反辐射无人机平台/图：台湾中时电子报   据台湾中时电子报报道，继日前台军被曝出或将量产1500公里中程导弹后，台中科院航空所长齐立平14日声称，台军已确定量产剑翔反辐射无人机，将分6年共生产104架，并叫嚣瘫痪辽宁舰编队的海基雷达系统是作战目标之一。消息一出，岛内网友讽刺说得容易，你聪明别人傻瓜?   台军所谓防务展览今天开始，齐立平昨日放言，剑翔无人机系统已具备作战能力，假想目标包含大陆辽宁舰航母编队舰艇。也因其机动部署特性，未来或进一步在外岛、舰艇上部署。当然，他仍不忘声老调重弹，称大陆对台威胁。   不过，台中科院两年前将剑翔列为重点展示装备时，就曾因其外型和以色列的Harpy无人机相近，被加拿大媒体质疑抄袭。尽管此后中科院辩解称，台军没有Harpy无人机，因而无从抄袭。但也可见此事从一开始就遭外界质疑。   不出意外，这次再提剑翔，依然不被看好。','paste','cmnee_test_12.txt',387,'2026-06-16 13:15:12'),(125,'[CMNEE #44] 英国皇家海军首艘新型驱逐舰机敏号在其首次导弹试射任务中成功发射了战斧弹道。 在试射中，战斧导弹的速度达到550英里/小时，该导弹长5.5米，重1300公斤，射程...','英国皇家海军首艘新型驱逐舰机敏号在其首次导弹试射任务中成功发射了战斧弹道。 在试射中，战斧导弹的速度达到550英里/小时，该导弹长5.5米，重1300公斤，射程超过1000英里。英国是唯一一个获得美国战斧导弹技术的国家。 据报道，机敏号目前正在墨西哥湾进行系统测试，该潜艇是英国皇家海军潜艇中武器携数带量最大的潜艇，能携带38枚战斧导弹和旗鱼鱼雷。机敏级核动力潜艇是英国皇家海军最先进的潜艇，将取代目前在役的特拉法尔加号级潜艇。其主要任务是执行反潜、反舰作战，以及收集情报保护英国的战略威慑和水面船只。同时还能使用战斧巡航导弹进行对陆打击。 该级潜艇的第一艘机敏号已经于2010年8月27日服役。目前该舰正在进行最后的海试工作，明年春天还将到美国继续海试，之后便返回英国进行训练，随后将会正式执行首次部署任务。','paste','cmnee_test_44.txt',355,'2026-06-16 13:15:12'),(126,'[CMNEE #123] 华盛顿消息-美国海军垂直起降无人机的升级版计划在今年十月进行首次飞行。   八月十三日，海军火力侦察兵项目经理帕特里克.史密斯上校，在国际无人机系统协会举办的2...','华盛顿消息-美国海军垂直起降无人机的升级版计划在今年十月进行首次飞行。   八月十三日，海军火力侦察兵项目经理帕特里克.史密斯上校，在国际无人机系统协会举办的2013年无人系统会议的新闻发布会上表示，MQ-8C火力侦察兵无人机首机采用了贝尔 407型直升机机身设计，而非MQ-8B火力侦察兵无人机所使用的施韦泽333型直升机机身。该机已被送往加利福利亚州的穆古角海军航空站，并将在那里开始首飞。   MQ-8C火力侦察兵无人机携带燃料充足，续航时间达12个小时。它能够携带比美国海军当前部署的MQ-8B火力侦察兵无人机更大的载荷。 按照计划，MQ-8C火力侦察兵无人机机于今年三月在阿利•伯克级导弹驱逐舰贾森•邓纳姆号上进行动态接口测试，将在2014年第三季度进行快速反应评估，并在当年的第四季度实现首次舰载部署。 美国海军已购买了12架MQ-8C型无人机，其中包含两架用于试验的飞机。该军种计划为总共96架MQ-8C火力侦察兵无人机机身采购48套无人机系统。','paste','cmnee_test_123.txt',430,'2026-06-16 13:15:12'),(127,'[CMNEE #127] 俄罗斯正在研制第五代无人战斗机和全新型导弹防御系统，能够同时打击多个超声速目标，并且在2013年莫斯科航展中进行过展出。 第5代无人战斗机的重量为20吨，外形酷...','俄罗斯正在研制第五代无人战斗机和全新型导弹防御系统，能够同时打击多个超声速目标，并且在2013年莫斯科航展中进行过展出。 第5代无人战斗机的重量为20吨，外形酷似T-50战斗机，另外还有多项特点与T-50战斗机类似。该项目正按照计划实施，目前已进入初步试验阶段。除第5代无人战斗机外，一位俄罗斯空军前指挥官还称，由于俄罗斯不能像美国的北约盟国一样向美国购买F-35第五代战机，而必须自主研发，因此目前正在研发可与之对抗的第6代无人机技术。 此外，俄罗斯还在研发S-500防空反导系统，并有可能于2017年装备。研发S-500防空反导系统是对美国在欧洲部署导弹防御系统的回应。 ','paste','cmnee_test_127.txt',288,'2026-06-16 13:15:12'),(128,'[CMNEE #136] 日本防务省计划采购两艘宙斯盾驱逐舰，这将使日本海上自卫队配备的宙斯盾驱逐舰数量增加到8艘，以更好的应对朝鲜的导弹威胁。同时，日本政府还计划在年底推出新的国防政策...','日本防务省计划采购两艘宙斯盾驱逐舰，这将使日本海上自卫队配备的宙斯盾驱逐舰数量增加到8艘，以更好的应对朝鲜的导弹威胁。同时，日本政府还计划在年底推出新的国防政策，以支撑其国家导弹防御计划。     日本海上自卫队目前共有四艘宙斯盾驱逐舰装备了标准-3导弹，具备弹道导弹拦截能力；另有两艘正在更新，将于2018年入役。内阁希望于2015年和2016年分别签署1艘宙斯盾驱逐舰的采购合同，并于2020财年完成部署。     今年春季，朝鲜拟对其运载火箭进行了试射，日本防务省于4月7日命令自卫队做好拦截准备，海上自卫队在日本海海域部署了2艘配备有标准-3导弹的宙斯盾驱逐舰，防空自卫队也在战略要地部署了爱国者PAC 3型地空导弹用于拦截。5月初，由于朝鲜取消的发射计划，防务省解除了这些部队的部署，并于6月28日完全撤消了部署的导弹。','paste','cmnee_test_136.txt',365,'2026-06-16 13:15:12'),(129,'[CMNEE #195] 作为伽利略项目的管理者，欧盟委员会已经决定为加速部署 伽利略空间段，在2016年增加一次联盟号火箭发射任务，以确认OHB公司建造的卫星的可用性。 额外的发射，计...','作为伽利略项目的管理者，欧盟委员会已经决定为加速部署 伽利略空间段，在2016年增加一次联盟号火箭发射任务，以确认OHB公司建造的卫星的可用性。 额外的发射，计划于2016年5月进行，将在法属圭亚那航天中心由阿里安航天公司负责2颗全面运行能力卫星入轨，此次发射属于该公司与欧空局的合同范围内。之前，阿里安航天公司已计划在2016年第4季度由阿里安-5ES火箭发射4颗伽利略导航卫星。 因此，2016年将有6颗新的伽利略卫星被部署，到年底使该星座的总数到达18颗。欧盟的伽利略项目旨在开发一个完整的在民用控制之下的全球卫星导航系统，该系统将包括30颗卫星，其中12颗卫星已经由阿里安航天公司发射入轨。 包括最新的任务，阿里安航天公司计划在2016年从圭亚那航天中心进行12次发射。','paste','cmnee_test_195.txt',339,'2026-06-16 13:15:12'),(130,'[CMNEE #301] 随着7月31日一架T129 ATAK直升机正式移交，土耳其航宇工业公司已经完成了土耳其陆军首批9架T129的交付工作。     土耳其陆军共订购了60架T129...','随着7月31日一架T129 ATAK直升机正式移交，土耳其航宇工业公司已经完成了土耳其陆军首批9架T129的交付工作。     土耳其陆军共订购了60架T129，并有40架增订意向。首批9架T129A型机是为了满足急迫使用需求紧急采购的，2014年开始交付，最终将升级为换装更先进武器系统的B型，而B型新机的交付工作预计很快也将启动。     TAI称T129直升机是同级别中最先进的战斗直升机，土耳其陆军已经投入作战使用。同时，TAI还表示T129 ATAK已做好向全球用户出口的准备，土耳其军方的支持使该型机具备非常强的市场竞争力。TAI目前正在向波兰推销T129 ATAK，用以替换米-24，并预计将在本月22-23日土耳其举行的Radom航展和9月莫斯科航展上进行展示。该型机的其他销售目标还包括独联体国家、亚洲和中东国家。','paste','cmnee_test_301.txt',366,'2026-06-16 13:15:12'),(131,'[CMNEE #389] 为期一周的印度-美国双边海军演习于这个星期四在印度西海岸开始，美国有750名海军人员参加了该次军事演习。该次演习代号为马拉巴尔演习，将在10月3号结束。 此次演...','为期一周的印度-美国双边海军演习于这个星期四在印度西海岸开始，美国有750名海军人员参加了该次军事演习。该次演习代号为马拉巴尔演习，将在10月3号结束。 此次演习的主要目的是增加两国的协同作战能力，包括舰对舰、对空作战和人员交换。美国海军参加军事演习的舰艇包括提康德洛加级导弹巡洋舰钱瑟勒斯威尔号 、斯普鲁恩斯级驱逐舰保罗・福斯特号和一架P-3C巡逻侦察机。演习过程中，两国部队将在多种技能区域内训练，包括直升机甲板、舰炮发射和反潜作战训练。这是马拉巴尔军事演习系列的第四次演习。 钱瑟勒斯威尔\'号和保罗・福斯特号在星期四到达印度科钦，钱瑟勒斯威尔号配备人员360名，驻扎在日本横须贺海军基地，保罗・福斯特号340名，母港在华盛顿埃弗雷德海军基地。 ','paste','cmnee_test_389.txt',325,'2026-06-16 13:15:12'),(132,'[CMNEE #498] 雷声公司已经赢得一份为美国海军海基防御系统发展标准导弹-3的工程和制造合同，合同价值8.814亿美元，为期3年。 SM-3的先进特点是拥有第三阶段火箭发动机，G...','雷声公司已经赢得一份为美国海军海基防御系统发展标准导弹-3的工程和制造合同，合同价值8.814亿美元，为期3年。 SM-3的先进特点是拥有第三阶段火箭发动机，GPS导航，和动能弹头，主要拦截和摧毁短程和中程弹导弹。SM-3是美国导弹防御局宙斯盾弹道导弹防御系统的主要组成部分。宙斯盾BMD巡洋舰USS Lake Erie号在2002年成功的进行了三次拦截弹道导弹目标的试验。 2002年9月，美国布什总统宣布美国的目标是在2004年~2005年之间完成导弹防御能力的研制测试，并在2005年部署多达20个海基拦截宙斯盾舰艇防御平台。 该项合同除了进行工程支持外，雷声公司海军对最初部署的5枚导弹进行生产和测试，同时继续同日本进行合作性研究和开发。该项合同还包括生产随后将部署的附加SM-3导弹产品。 附图：SM-3导弹和发射图片。','paste','cmnee_test_498.txt',365,'2026-06-16 13:15:12'),(133,'[CMNEE #526] 10月29日在伊拉克作战中，美国海军肯尼迪号航母上的第34攻击战斗机中队的飞机投下2枚代号为GBU-38的227千克联合直接攻击弹药。 这此成功使用是美国航空系...','10月29日在伊拉克作战中，美国海军肯尼迪号航母上的第34攻击战斗机中队的飞机投下2枚代号为GBU-38的227千克联合直接攻击弹药。 这此成功使用是美国航空系统司令部、舰队部队司令部和美国第5舰队致力于的快速测试、采购和部署新武器，以满足紧急作战的要求下进行的。美国官员称，这是美国海军首次使用现役武器库中最新的武器，由于其精度和可靠性高，适应于现在伊拉克进行的城市巷战。 GBU-38于9月28日在加利福尼亚州NAVAIR的试验场完成了初始作战评估，10月8日获得初始作战能力，比计划提前了8个月，最终使实战使用得以提前。 ','paste','cmnee_test_526.txt',264,'2026-06-16 13:15:12'),(134,'[CMNEE #538] 上周四，朝鲜海军官员指谴责韩国舰船入侵其黄海的领海，并警告紧张局势升级可能会导致发生冲突。此前，朝鲜刚在黄海完成短程导弹的发射，这种类似局面曾在1999年和20...','上周四，朝鲜海军官员指谴责韩国舰船入侵其黄海的领海，并警告紧张局势升级可能会导致发生冲突。此前，朝鲜刚在黄海完成短程导弹的发射，这种类似局面曾在1999年和2002年时出现。 朝鲜国家通讯社KCNA源引一位海军发言人的话称：局势变得非常紧张，韩国军舰不断入侵朝鲜领海的军事挑衅可能会引起海上冲突。 这位发言人表示，从9月初开始，韩国海军派遣了更多的军舰进入朝鲜的领海，试图将北方边界线的争议地区合法化。 在1950-1953年的南北冲突结束之后，韩国和朝鲜就一直处于冲突状态，没有实现和平谈判。朝鲜一直不承认由美国所领导的联合国司令部在战争结束之后所划分的海上边界线。在该区域内，1999年和2002年6月都发生了海上冲突，造成6名韩国船员死亡。这位发言人表示，海军一直处于战备状态，以应对任何海上入侵。 朝鲜于星期二在黄海海域发射了两枚短程导弹，韩国官员称之为例行的军事演习。韩国新闻媒体于周四报道，朝鲜计划在同一区域进行10枚或者更多短程导弹的集中发射测试。在此之前，朝鲜已经在海上完成了多次短程导弹的测试，韩国通常称之为常规演习的一部分。','paste','cmnee_test_538.txt',472,'2026-06-16 13:15:12'),(135,'[CMNEE #612] 从10月份开始，美国空军开始将美国导弹上的旧核弹头换成更先进设计的W87弹头。 据Inside Bay Area报道，技术人员开始为内布拉斯加州和怀俄明州的导弹...','从10月份开始，美国空军开始将美国导弹上的旧核弹头换成更先进设计的W87弹头。 据Inside Bay Area报道，技术人员开始为内布拉斯加州和怀俄明州的导弹发射井中的大约300枚导弹安装弹头。 国防官员称，通过更换核弹头设计，美国军方将节约数亿美元用于维护弹头的资金。美国将在2012年前将部署在陆基导弹上的核弹头数量削减一半。 为了实现旧设计的更换，美国经过了3年的研究工作，花费2.5亿美元。 要更换弹头，科学家们必须确保W87弹头在略有不同的条件下还能在民兵-3型导弹上发挥作用。 劳伦兹利弗莫尔和桑迪亚实验室的科学小组通过一系列基础机试验来确保新弹头和火箭包的可靠性。 新设计还进行了三次飞行试验。','paste','cmnee_test_612.txt',305,'2026-06-16 13:15:12'),(136,'[CMNEE #623] 美国一位太平洋司令部官员表示，鉴于朝鲜在2006年进行的导弹试验，美国2007年将对太平洋地区导弹探测系统进行升级。     已部署传感器联接组件，以探测朝鲜指...','美国一位太平洋司令部官员表示，鉴于朝鲜在2006年进行的导弹试验，美国2007年将对太平洋地区导弹探测系统进行升级。     已部署传感器联接组件，以探测朝鲜指向美国的导弹发射。阿留申群岛附近一个经改装的石油平台还装备了一台海基X波段雷达，这台传感器可探测并跟踪飞向美国的导弹。当前导弹防御系统仍然依靠空中预警系统，与其他传感器联合将可以根据导弹的上升轨迹，发现并跟踪目标。     美国海军舰艇已装备了宙斯盾战斗系统和综合导弹制导系统，日本海军舰艇舰装备了改进型侦查雷达，并向太平洋地区加大兵力投入。 陆基拦截器与之前美国海军太平洋军舰部署的最新改良标准导弹，将摧毁导弹。     除此之外，系统网络也将在今年升级。这是美国太平洋司令部首次对这些系统进行部署与试验。','paste','cmnee_test_623.txt',334,'2026-06-16 13:15:12'),(137,'[CMNEE #648] 海狼号快速攻击潜艇于7月22日抵达位于太平洋西北部布莱默顿的新母港吉塞普海军基地，并在该基地举行了小规模的欢迎仪式。该潜艇是从以前的新伦敦母港转移至布莱默顿，并...','海狼号快速攻击潜艇于7月22日抵达位于太平洋西北部布莱默顿的新母港吉塞普海军基地，并在该基地举行了小规模的欢迎仪式。该潜艇是从以前的新伦敦母港转移至布莱默顿，并将永远驻扎在布莱默顿。 美海军有关人士表示，此次潜艇更换母港主要是为了增强太平洋舰队的潜艇作战能力，将有60%的美海军潜艇将永久性的驻扎在太平洋。该潜艇停靠在新的母港以后将加入停靠在布莱默顿母港的斯坦尼斯号航母战斗群和由8艘停靠在吉塞普-班戈海军基地的三叉戟弹道导弹潜艇组成的舰队。 海狼号潜艇主要采用自治方式抵抗强大的潜艇和水面舰艇威胁，其较高的作战速度超过了美海军的其他任何潜艇。该艇是海狼级潜艇的第一艘于1997年服役，长353英尺，取代了规模较小的洛杉矶级潜艇。海狼号高速潜艇携带140名船员，其检查和维护工作将在Puget Sound海军船厂进行。','paste','cmnee_test_648.txt',359,'2026-06-16 13:15:12'),(138,'[CMNEE #657] 俄罗斯媒体9月1日报道，作为普京总统核防御现代化项目的一部分，俄罗斯将于2007年12月完成新型洲际弹道导弹的二次部署。     美国计划在东欧部署导弹防御使得...','俄罗斯媒体9月1日报道，作为普京总统核防御现代化项目的一部分，俄罗斯将于2007年12月完成新型洲际弹道导弹的二次部署。     美国计划在东欧部署导弹防御使得俄罗斯与北约间的关系一度紧张。莫斯科反对该计划称这可能威胁其国家安全，而华盛顿则坚持这一防御只是用于对抗伊朗等被美国称为无赖国家的袭击。此次部署就是在这样的状况下发生的。     作为未来20至30年确保俄罗斯安全的新一代武器的一部分，白杨－M移动导弹将部署在距莫斯科东北部150英里处的Teikovo。首个编队已于2006年12月开始部署，但未透露关于导弹数量的任何消息。     22米长的白杨－M是一种携带单弹头的洲际弹道导弹。在苏联解体后的90年代开始研制，其后进行了升级。它既能够从发射井发射也可以使用隐藏在丛林中的移动发射装置发射。','paste','cmnee_test_657.txt',352,'2026-06-16 13:15:12'),(139,'[CMNEE #852] 美国华盛顿时间9月17日消息，美国政府目前正在制定旨在报复上周攻击世贸中心和五角大楼的恐怖分子的反恐怖计划。先前讨论的一些计划包括空袭，部署特种作战部队以及对阿...','美国华盛顿时间9月17日消息，美国政府目前正在制定旨在报复上周攻击世贸中心和五角大楼的恐怖分子的反恐怖计划。先前讨论的一些计划包括空袭，部署特种作战部队以及对阿富汗等包庇恐怖分子的国家全面动武等。据称，美国海军的罗斯福号航母正在驶向海湾地区，它将与已部署在那里和印度洋的航空战斗群会合。另外，美国方面还在巴基斯坦提出希望能够利用其机场跑道升降F-15和F-16战斗机进行空中打击。但截止17日，巴方仅表示同意美国使用其领空，但不包括机场跑道。分析人士指出，如果最终巴方拒绝美国的要求，那么美军有可能从印度洋、海湾地区的基地或位于土耳其的北约基地发动远程空袭。五角大楼的官员还证实，来自北卡莱罗纳州第82空降师以及来自肯塔基州的第101空降师的空降兵已被告之严阵待命。分析人士预测这两个空降师的伞兵和包括海军特种作战部队在内的特种作战司令部下辖部队将成为美国反恐怖行动的先遣分队。但是，五角大楼官员拒绝透露这一反恐怖行动到底将采取何种形式。','paste','cmnee_test_852.txt',419,'2026-06-16 13:15:12'),(140,'[CMNEE #873] 为增强土耳其海军的情报能力，土耳其军方和装备采办部门决定开始设立无人直升机联合建造项目，目前正在寻找合作伙伴。相关部门将在2011年底之前发布提案申请。 一位土...','为增强土耳其海军的情报能力，土耳其军方和装备采办部门决定开始设立无人直升机联合建造项目，目前正在寻找合作伙伴。相关部门将在2011年底之前发布提案申请。 一位土耳其国防部官员称，国外的竞标公司都可以参与本次竞争，但是他们必须要同意与土耳其主承包商进行合作。 据来自工业部门的消息称，土耳其本地的主承包商极有可能是土耳其航空工业公司。2010年12月，土耳其航空工业公司建造的首架无人直升机样机蚊子装备国产Cirit 70毫米激光寻的制导火箭弹试飞成功。 该无人直升机联合建造项目首批计划建造30架无人直升机。 装备采办部门官员表示，关于该无人平台最初的规格参数将会是：行程180公里，飞行时间超过10小时。在蚊子无人机首次试飞中，其飞行时间为1.5小时。 根据合同要求，即将联合建造的无人直升机必须要能够进行垂直起降，因为这些无人直升机将在舰艇上执行作战任务。 当无人直升机完成建造工作后，首先将会被部署在船坞登陆舰上，而船坞登陆舰正是土耳其在计划采购的一类装备。随后，这些直升机将会部署在土耳其轻护舰和护卫舰上。','paste','cmnee_test_873.txt',457,'2026-06-16 13:15:12'),(141,'[CMNEE #895] 哈里斯公司获得了一份2.35亿美元的合同，为澳大利亚国防部战术无线电台现代化项目的下一阶段研发工作，交付猎鹰战术无线电系统。所交付的无线电台将为澳大利亚武装部队...','哈里斯公司获得了一份2.35亿美元的合同，为澳大利亚国防部战术无线电台现代化项目的下一阶段研发工作，交付猎鹰战术无线电系统。所交付的无线电台将为澳大利亚武装部队提供可靠的1类加密战术话音和数据通信能力。       哈里斯公司将为澳大利亚国防部交付的战术无线电台包括猎鹰III AN/PRC-152多频带、多模式手持战术无线电台，可实现视距和超视距通信。该无线电台是部署数量最多的获得联合战术无线电系统软件通信体系认证的手持无线电台。到目前为止，美国、北约国家和其他盟国总共部署了超过160000台。       此外，澳大利亚国防部还要求哈里斯公司交付猎鹰II AN/PRC-150便携式无线电台。该无线电台是目前仅有的使用1类加密技术的高频无线电台。两种无线电台都将按照联合计划2072项目的要求完成交付工作。 ','paste','cmnee_test_895.txt',358,'2026-06-16 13:15:12'),(142,'[CMNEE #913] 印度已收到巴西航空工业公司交付的首架EMB-145空中预警与控制飞机。巴西飞机制造商表示，交付地点在巴西航空工业公司总部圣若泽杜斯坎普斯。    该飞机已经完成...','印度已收到巴西航空工业公司交付的首架EMB-145空中预警与控制飞机。巴西飞机制造商表示，交付地点在巴西航空工业公司总部圣若泽杜斯坎普斯。    该飞机已经完成了地面和飞行试验，达到了巴西航空工业公司和印度国防研究与发展组织机载系统中心的既定目标。随后飞机将集成DRDO的任务系统，移交给印度空军。印度空军2008年耗资2.08亿美元订购了3架EMB-145预警机。    该机在机身上方整流罩上配备DRDO开发的有源电子扫描阵列雷达。EMB-145的设计基于ERJ-145支线客机，具有一个空中加油探头并增强了制冷功能。    此前巴西航空工业公司已生产了10架EMB-145 预警机，交付巴西、希腊和墨西哥。所有飞机都已配备了萨伯微波系统公司生产的爱立眼监视雷达。    ','paste','cmnee_test_913.txt',338,'2026-06-16 13:15:12'),(143,'[CMNEE #965] 美国雷神公司近日与日本海上自卫队签订合同，为后者升级密集阵近防武器系统。根据这份总价2.05亿美元的多年期批量采购合同，雷神公司将负责为海上自卫队提供近防系统升...','美国雷神公司近日与日本海上自卫队签订合同，为后者升级密集阵近防武器系统。根据这份总价2.05亿美元的多年期批量采购合同，雷神公司将负责为海上自卫队提供近防系统升级套件、保障装备和备件。       雷神公司海上防务导弹系统生产线副主任里克・尼尔逊介绍称，面对全球范围内不断增加的威胁，密集阵系统可为舰艇和舰员提供最关键的内层防护。由于采用了传感器阵列，密集阵系统可以探测并拦截来自海陆空等不同范围的威胁，如直升机、漂雷、火炮、制导武器和陆基反舰导弹等。        密集阵近防系统集成了由计算机控制雷达和20毫米速射炮系统，可自动识别、跟踪并摧毁那些已经突破其他舰艇防御系统的危险目标。       为了扩大对来袭反舰导弹、旋翼机、固定翼飞机及其他威胁的拦截范围，舰载自卫系统海拉姆反舰导弹防御系统配备了升级版密集阵Block 1B传感器和滚动弹体导弹部件。       SeaRAM系统目前已经部署在美国海军独立级近海战斗舰上，包括独立号和科罗纳多号。','paste','cmnee_test_965.txt',428,'2026-06-16 13:15:12'),(144,'[CMNEE #1051] 莱茵金属公司正在努力促成为德国联邦国防军研制并生产第四批IdZ-eS士兵系统的合同。这份合同的预算约为3.5亿欧元；若获得批准，预计将于2017年第二季度签订。...','莱茵金属公司正在努力促成为德国联邦国防军研制并生产第四批IdZ-eS士兵系统的合同。这份合同的预算约为3.5亿欧元；若获得批准，预计将于2017年第二季度签订。 2006年，莱茵金属公司获得了第二代IdZ-eS士兵系统的初始研制合同；2012年，获得了首份标准生产合同，并于2013年1月开始交付；2013年3月，IdZ-eS士兵系统正式在德国列装，并于2013年6月首次部署在阿富汗作战。 截至目前为止，莱茵金属公司已向德国总共交付了900套IdZ-eS士兵系统，合同总价值1.38亿欧元。第三批于2014年3月交付德国陆军。实际作战使用效果将反馈于第四批的设计当中。由于采用了轻量化的电子设备，该型士兵系统的重量将减轻20%，并将采用一种基于莱茵金属公司标准、安装在武器上的无线按讲开关，与原本采用蓝牙的配置相比，电池的使用时间大大延长。','paste','cmnee_test_1051.txt',371,'2026-06-16 13:15:12'),(145,'[CMNEE #1060] 美国国务院已经批准向日本出售价值1.333亿美元的标准-3导弹 Block IIA 导弹，此项军售项目正在等待国会批准。根据合同，美国将向日本提供四枚标准-3 ...','美国国务院已经批准向日本出售价值1.333亿美元的标准-3导弹 Block IIA 导弹，此项军售项目正在等待国会批准。根据合同，美国将向日本提供四枚标准-3 Block IIA导弹以及四套Mk 29海麻雀导弹发射装置。该合同还包括向日本技术援助，以及运输、工程和后勤保障服务。     雷声公司生产的标准-3拦截弹是一种用来对付近程和中程弹道导弹的防御性武器，可从陆基和海基部署的Mk 29导弹发射装置发射。     此次军售项目旨在提升日本海上自卫队的弹道防御能力。BAE系统公司为标准-3导弹，生产Mk 29发射装置。','paste','cmnee_test_1060.txt',262,'2026-06-16 13:15:12'),(146,'[CMNEE #1573] 9月30日，在费罗尔船厂举行的一次仪式上，纳凡蒂亚公司向西班牙海军移交胡安・卡洛斯一世号两栖攻击舰。西班牙国王胡安・卡洛斯一世主持这艘两栖舰的接收仪式，胡安・卡...','9月30日，在费罗尔船厂举行的一次仪式上，纳凡蒂亚公司向西班牙海军移交胡安・卡洛斯一世号两栖攻击舰。西班牙国王胡安・卡洛斯一世主持这艘两栖舰的接收仪式，胡安・卡洛斯一世号是纳凡蒂亚公司有史以来建造的最大舰艇，也将是西班牙海军有史以来运行的最大舰艇。 胡安・卡洛斯一世号两栖攻击舰于2005年铺设龙骨，2010年3月10日下水。对于纳凡蒂亚公司而言，胡安・卡洛斯一世号的建造给船厂带来了650万工时的生产工作和85万工时的工程工作，这直接和间接地转化为了4000多个就业岗位。此外，共有33个企业作为分包商或供应商参与了胡安・卡洛斯一世号的建造。 胡安・卡洛斯一世号两栖攻击舰的大小意味着它是有史以来纳凡蒂亚公司为西班牙海军建造的最大舰艇，一些外国海军也对这型设计感兴趣。   2007年，澳大利亚皇家海军向纳凡蒂亚公司订购了两艘类似的舰艇。  ','paste','cmnee_test_1573.txt',372,'2026-06-16 13:15:12'),(147,'[CMNEE #1604] 美国空军和波音公司在8月21日完成了KC-46加油机的关键设计评审。该里程碑的完成时间比合同进度安排提前了1个月，原定时间是9月24日。    为达到此目标，波...','美国空军和波音公司在8月21日完成了KC-46加油机的关键设计评审。该里程碑的完成时间比合同进度安排提前了1个月，原定时间是9月24日。    为达到此目标，波音和美国空军开展了10个月的部件和子系统设计审查。CDR完成后，KC-46设计冻结、制造和试验工作将很快展开。首架KC-46的制造已经开始，6月26日，波音开始首架飞机机翼的装配，之后将改装为KC-46的波音767-2C基本型飞机将在2014年中期首飞。首架装备系统的KC-46加油机计划2015年初首飞。    波音公司按合同到2017年8月前，将制造4架试验飞机和交付18架作战就绪的加油机。如果美国空军全部履行其意向订货，将总计购买179架该加油机。','paste','cmnee_test_1604.txt',308,'2026-06-16 13:15:12'),(148,'[CMNEE #1605] 可切断10000部手机信号干扰的新型三坐标雷达近日在怀特岛的秘密电磁雷达测试基地成功开展集成试验。 这次测试的工匠三坐标雷达比在英国伊丽莎白女王级航母上安装的雷...','可切断10000部手机信号干扰的新型三坐标雷达近日在怀特岛的秘密电磁雷达测试基地成功开展集成试验。 这次测试的工匠三坐标雷达比在英国伊丽莎白女王级航母上安装的雷达更加先进。 工匠雷达的试验将主要测试一系列集成系统，包括三坐标对空监测、目标识别、舰上空中交通管理系统。工匠三坐标雷达可提供广泛的空中交通控制和中程战术图像能力，同时追踪900余个目标，并可识别网球大小以三倍声速运动的点目标。 BAE系统公司新型雷达的测试基地位于岛上的萨默顿机场旧址。该机场1916年投入使用，20世纪30年代用于飞机组件的制造、测试和伦敦与怀特岛间的航班运营，1959年被英国迪卡唱片公司收购。 BAE系统公司生产的工匠雷达同样在伊丽莎白女王级航母战斗管理系统使用，并可接收任务系统测试设备中的模拟本舰信号。此外，该型雷达同样用于伊丽莎白女王级航母的敌我识别系统。 该中程雷达系统2012年完成工厂测试，并在2013年早期用于BAE系统公司的航母联合体电磁环境评估设施。','paste','cmnee_test_1605.txt',426,'2026-06-16 13:15:12'),(149,'[CMNEE #1695] 《波音》网站2002年7月25日报道，美国波音公司生产的12架F/A-18E/F超黄蜂战斗机，于7月24日从位于勒莫尔的美国海军航空站，飞到航行在太平洋上的亚布...','《波音》网站2002年7月25日报道，美国波音公司生产的12架F/A-18E/F超黄蜂战斗机，于7月24日从位于勒莫尔的美国海军航空站，飞到航行在太平洋上的亚布拉罕・林肯号航空母舰上，加入第14舰载航空联队，随时可以投入作战使用。超黄蜂战斗机首次进入美国海军服役，标志着波音公司、参与该项目研制的各公司以及美国海军多年辛勤劳动所取得的成果。在该项目计划实施的整个过程中，超黄蜂战斗机一直是按时、甚至提前交付的。1995年9月首次交付7架试飞型战斗机。在完成试飞计划后，于1998年12月交付首架生产型战斗机。在完成美国海军历史上最严格的鉴定试飞后，于1999年1月在勒莫尔的美国海军航空站成立了第一个超黄蜂战斗机中队。到2002年6月为止，已经交付了第100架生产型战斗机。','paste','cmnee_test_1695.txt',337,'2026-06-16 13:15:12'),(150,'[CMNEE #1702] 2019年1月26日，新加坡科技工程有限公司海洋系统分部建造的无畏号近海任务舰举行了下水仪式，这是独立级近海任务舰的第八艘也是最后一艘。该级舰目前已有五艘服役，...','2019年1月26日，新加坡科技工程有限公司海洋系统分部建造的无畏号近海任务舰举行了下水仪式，这是独立级近海任务舰的第八艘也是最后一艘。该级舰目前已有五艘服役，两艘将于今年交付，八艘舰艇将在2020年全部投入使用。无畏号下水是新加坡海军持续转型的一个重要的里程碑，使其能够继续保护新加坡水域的主权和安全。该级舰艇入役以来参与了多次任务，包括日常海上安全巡逻、在新加坡举行的朝美首脑会晤、东盟多边海军演习和新加坡-印度海上双边演习等。   新加坡科技工程有限公司于2013年获得防务部门的合同，为新加坡海军设计和制造8艘近海任务舰。迄今为止，已服役五艘舰艇，分别是独立号、主权号、统一号、正义号和顽强号，最后三艘舰艇坚韧号、不屈、无畏号目前已全部下水。八艘独立级近海任务船将取代该集团在上世纪九十年代设计和建造的11艘无畏级巡逻舰。   ','paste','cmnee_test_1702.txt',368,'2026-06-16 13:15:12'),(151,'[CMNEE #1704] 未来两年，美海军计划在一艘驱逐舰上安装舰载高能激光武器，用于测试舰艇与定向能武器系统间的集成。     按计划，海军将在2021年将高能激光与一体化光学炫目和监...','未来两年，美海军计划在一艘驱逐舰上安装舰载高能激光武器，用于测试舰艇与定向能武器系统间的集成。     按计划，海军将在2021年将高能激光与一体化光学炫目和监视武器系统安装至阿利・伯克IIA型驱逐舰上。HELIOS系统功率约60千瓦，较5年前海军在庞塞号前沿浮动基地上测试的激光武器系统输出功率更高，作战对象是快速攻击小艇和小型无人机。     去年，洛马公司获得1.5亿美元合同，开发两套HELIOS系统，一套用于岸上测设，第二套将装备海军驱逐舰。根据美海军海军水面舰载激光武器系统增量1项目，海军曾计划2020年完成安装。     HELIOS将用于测试激光武器与宙斯盾作战系统间的集成，还将为舰艇提供更精确的目标指示数据。     与当前作战系统集成是高能激光武器上舰面临的重要问题之一，舰艇必须移除部分现有武器才可实现这一目标。HELIOS系统上舰后，海军还将学习通过宙斯盾系统控制激光武器的相关操作。','paste','cmnee_test_1704.txt',406,'2026-06-16 13:15:12'),(152,'[CMNEE #1776] 欧洲有伽利略计划，但并非唯一想要建造与GPS竞争的卫星导航系统的地区。美国对世界唯一全功能卫星导航系统GPS的控制，促使印度、日本等国也在研发区域覆盖的导航系统...','欧洲有伽利略计划，但并非唯一想要建造与GPS竞争的卫星导航系统的地区。美国对世界唯一全功能卫星导航系统GPS的控制，促使印度、日本等国也在研发区域覆盖的导航系统。 俄罗斯总统普京已经力促完成全球导航卫星系统，以减少俄罗斯对GPS的依赖。他希望该系统能在2007年开始运行。 日本正致力于由三颗卫星组成的准天顶卫星系统中第一颗卫星的建造。首颗QZSS卫星预计于2009年发射，卫星将进入高椭圆轨道。 印度有两个导航计划。他们计划发射一个地球同步卫星系统，以提高用于印度机场与空中的GPS信号的精度。这个GEO增强导航系统显然得到了美国的支持，雷神公司正为此系统提供地面终端。2006年印度还宣布要研发一个印度区域导航卫星系统，在2011年之前使7颗卫星组成的星座就位。 对于区域部署而言，静地轨道是非常好的选择。美国部分官员曾鼓吹使用静地轨道测试美国导航卫星能力。美国已决定发射首批6颗中轨地球轨道卫星，将提供4～6小时的典型覆盖。','paste','cmnee_test_1776.txt',415,'2026-06-16 13:15:12'),(153,'[CMNEE #1791] 希拉库思研究公司的雷达日前成功的完成了性能测试，在360度反火力模式下对抗了迫击炮和火箭弹。该雷达是洛克西德・马丁公司增强型AN/TPQ-36反火力目标获取雷达...','希拉库思研究公司的雷达日前成功的完成了性能测试，在360度反火力模式下对抗了迫击炮和火箭弹。该雷达是洛克西德・马丁公司增强型AN/TPQ-36反火力目标获取雷达的原型。 测试旨在评估雷达的能力是否能够满足美国陆军在近期的作战需求规划中所勾勒出的需求。在测试中，EQ-36原型雷达在360度模式下成功的锁定了火箭弹和迫击炮弹的火力位置，在去年11月和12月所举行的为期7天的实地火力测试中，雷达未出现一次错误报警。 美国陆军新型的EQ-36雷达最终将提供90度模式下或是360度模式下探测、区分、跟踪、判断敌方间接火力的位置的能力，如迫击炮、火箭弹等。EQ-36将最终取代TPQ-36、TPQ-37以及其他冷战时期的中程雷达，这些雷达仅仅工作在90度模式下。 美国洛克西德・马丁公司将于2009年夏向美国陆军交付首批2部EQ-36雷达，2009年秋交付第3部和第4部，2010年交付第5部。','paste','cmnee_test_1791.txt',394,'2026-06-16 13:15:12'),(154,'Yemen\'s Houthi armed group seizes the strategic Red Sea outpost of the Hanish Islands.','Xinhua News Agency, Kuwait City, Sept. 10 (Reporter Yin Ke) — Aden message: Yemeni government officials said on the 10th that after government naval forces withdrew from the strategic Red Sea outpost of the Hanish Islands, Yemen\'s Houthi armed group has deployed forces on the islands. That evening, Yemeni government forces designated an area along the country\'s western coast as a \"combat zone.\" The anonymous government official told Xinhua reporters that after Yemeni government naval forces withdrew from the Hanish Islands on the afternoon of the 10th, the Houthi armed group immediately entered and established military positions on the islands. The Hanish Islands are located north of the Bab el-Mandeb Strait, close to major international shipping lanes, and have important strategic value for monitoring and safeguarding the safety of maritime traffic. On the same day, after several hours of fierce exchanges of fire, the Houthi armed group captured the strategic location of Mocha, a Red Sea port city in Yemen\'s southwestern Taiz Province, forcing government forces to retreat southward to the Dhubab area between Mocha and the Bab el-Mandeb Strait. That evening, Yemeni government forces announced that an area along the country\'s western coast would be designated a \"combat zone.\" Government forces spokesman Majid al-Nuzaili said in a statement broadcast on Yemeni state television that government forces would use \"all types of weapons and firepower\" to strike Houthi personnel and military equipment operating within the designated area.','paste',NULL,1555,'2026-09-11 13:52:32');
